var e=JSON.parse(`{"wrist-circles":{"name":"手腕繞環","description":"站直，手肘放鬆，前臂放在身前。雙腕緩慢畫圓，一個方向四拍，再換方向四拍，手指保持放鬆。","goodFor":"熱身手腕和前臂，它們是所有道具動作中出力最多的部位。","alignmentCues":["手肘保持不動，只有手腕在動。","讓圓圈又大又流暢。"],"commonMistakes":["繞得太急，變成了甩手腕。"]},"arm-circles":{"name":"手臂繞環","description":"雙腳與髖同寬，手臂伸直。雙臂向前大幅繞環四拍，再向後四拍，讓肩胛骨自然滑動。","goodFor":"開啟肩膀，為棍花和頭頂呼啦圈動作做準備。","alignmentCues":["手臂經過頭頂時，肋骨保持下沉。","下襬時呼氣。"]},"shoulder-rolls":{"name":"聳肩繞環","description":"雙臂自然垂在身體兩側。把肩膀聳到耳邊，向後向下繞，緩慢迴圈重複。","goodFor":"釋放讓拋接變得僵硬短促的緊張感。"},"neck-rolls":{"name":"頸部半圓繞環","description":"下巴向胸口低垂，緩慢地從一側肩膀掃到另一側，畫半圓。不要讓頭向後仰。","goodFor":"在長時間抬頭看拋接之前放鬆頸部。","avoidIf":["頸部受傷或移動頭部時頭暈。"]},"hip-circles":{"name":"髖部繞環","description":"雙手叉腰，膝蓋微屈。髖部緩慢畫圓，一個方向兩小節，再換方向兩小節，頭部保持水平。","goodFor":"為腰部呼啦圈做準備，讓身體進入流動狀態。"},"torso-twists":{"name":"軀幹扭轉","description":"雙腳分開，手臂放鬆。左右轉動肋骨，讓手臂像空袖子一樣甩動並纏繞身體。","goodFor":"喚醒旋轉感，為棍花編織和呼啦圈傳遞做準備。"},"knee-bounce":{"name":"膝蓋彈動","description":"雙腳站在髖部正下方，每一拍透過膝蓋輕輕彈動，手臂放鬆擺動。在腿裡找到音樂的節奏。","goodFor":"在拿起道具之前，先把節拍放進身體裡。"},"one-ball-toss":{"name":"單球拋接","description":"右手在腰高處持一個球。先向內舀，然後沿弧線丟擲，最高點剛好在眼睛上方，落入左手。用同樣的方式拋回。眼睛盯著弧線最高點，不要看手。","goodFor":"建立所有雜耍模式的基本弧線。","alignmentCues":["手肘貼近身體兩側，前臂保持水平。","每次丟擲的最高點高度相同。","在腰高處接住，讓手稍微緩衝。"],"commonMistakes":["向前拋，導致你得追著球走。","盯著手而不是最高點。"]},"two-ball-exchange":{"name":"雙球交換","description":"每隻手各持一個球。右手沿弧線丟擲；當它到達最高點時，左手從內側在它下方丟擲。接住兩個球，暫停。然後從左手開始。","goodFor":"教你交換：第二個球在第一個球到達最高點時丟擲。","alignmentCues":["第二個球在最高點時丟擲，絕不能提前。","第二個球從第一個球內側丟擲。"],"commonMistakes":["把第二個球橫傳過去，而不是丟擲去。","同時丟擲兩個球。"]},"cascade":{"name":"三球瀑布","description":"右手兩個球，左手一個球。從右手丟擲；當它到達最高點時從左手丟擲；當那個到達最高點時再從右手丟擲。每次拋球都踩在節拍上，以8字形弧線交叉到另一隻手。","goodFor":"雜耍的基礎模式。","modifications":["練習flash：三次拋球，三次接球，停下。"],"deepen":["用更快的節奏雜耍，拋球高度更低。","數到20次接球且不掉球。"],"alignmentCues":["從內側丟擲，在外側接住。","最高點齊平，在眼睛高度。","如果你總是向前走，就靠牆站立。"],"commonMistakes":["向前拋球並追著模式跑。","一旦有一個拋球出錯就急著趕節奏。"]},"reverse-cascade":{"name":"反瀑布","description":"把瀑布翻轉過來：每個球都從外側丟擲，越過模式的頂部，然後從中間落下進入另一隻手。","goodFor":"訓練從外側拋球，併為Mills Mess等技巧打下基礎。","alignmentCues":["拋球從飛來的球上方繞過。","在中心接住。"]},"siteswap-423":{"name":"423","description":"一個三球模式：一次高自拋（4），一個持球（2），然後一次瀑布拋（3）。4在同一側向上；2只是持住一拍。","goodFor":"你的第一個siteswap技巧：教你高拋和持球。"},"siteswap-441":{"name":"441","description":"兩次留在各自一側的高拋（4, 4），接著一次快速橫傳（1）從一隻手到另一隻手。","goodFor":"建立高拋和快速傳遞之間的節奏感。"},"two-in-one":{"name":"單手兩球","description":"用一隻手雜耍兩個球，做並排的柱狀或向外的小圓，每隔一拍拋一次。兩隻手都要練習。","goodFor":"四球雜耍的構建模組。"},"siteswap-531":{"name":"531","description":"一次很高的交叉拋（5），一次瀑布拋（3）和一次快速橫傳（1）。5向上飛，而另外兩個球在下面繼續運作。","goodFor":"高度控制和展示型三球技巧。"},"shower":{"name":"三球淋浴","description":"球沿圓形運動：右手把每個球高高拋到左邊，左手把每個球直接傳回右邊。","goodFor":"經典的圓形模式；訓練快速的手到手傳遞。"},"mills-mess":{"name":"米爾斯梅斯","description":"一種三球瀑布，手臂不斷交叉和展開，所以每次拋球都來自身體的另一側。球的軌跡形成編織圖案。","goodFor":"一個著名的觀眾喜愛技巧，能提升協調性。"},"four-ball-fountain":{"name":"四球噴泉","description":"每隻手在自己的柱狀空間裡雜耍兩個球，雙手交替拋球，所以模式從不交叉。","goodFor":"你的第一個四球模式。"},"sync-fountain":{"name":"同步噴泉","description":"四個球，雙手在同一時刻丟擲，各自拋向自己的一側。","goodFor":"建立對稱性，並通向同步技巧。"},"five-ball-cascade":{"name":"五球瀑布","description":"五球cascade：高拋、快速，形成高聳的交叉模式。預計需要數月的練習。","goodFor":"專注雜耍者的里程碑。"},"tennis":{"name":"網球","description":"一個級聯，其中一個球，即“網球” ，總是在圖案的頂部而不是中間行進。無論哪隻手握住它，它都會把它扔到外面，讓它像網上的集會一樣在頂部丟擲。","goodFor":"第一步進入外面投擲，而計時保持平原級聯。","alignmentCues":["將一個球作為網球放置在視野中。","從外面扔出去，和其他人一樣高。"],"commonMistakes":["丟失了哪個球越過的軌道。","將球扔得比其他人高。"]},"half-shower":{"name":"半淋浴","description":"一隻手將每個球扔到頂部，另一隻手將每個球扔到下面。兩個弧線分為高外徑和低內徑，球互相追逐。","goodFor":"將雙手分成兩個角色，同時保持均勻的節奏。","alignmentCues":["過度的手丟擲外面，觸控更高。","手下保持其投擲緊密和內側。"],"commonMistakes":["雙手飄回到普通的級聯投擲。","當弧線高度相同時，中間會發生碰撞。"]},"claw-cascade":{"name":"爪級聯","description":"瀑布抓住了手掌。每隻手都向上伸出，從空中抓起球，然後向下拉，轉身投擲。手看起來像是在抓球。","goodFor":"形成主動抓握和強勁的手腕轉動。","alignmentCues":["伸手去接球，手指張開。","向下拉，一次性翻轉手腕。"],"commonMistakes":["抓得很晚，所以球擊中了手背。","由於轉彎時間太長，投擲得太低。"]},"chops":{"name":"印章","description":"每次接球后，手將球高高地抬過身體，從遠處投擲下來。手臂像切片一樣互相擺動，球在下面落入一個緊密的級聯。","goodFor":"大臂攜帶，級聯時序仍在下方。","alignmentCues":["抓住高處，攜帶，砍下並投擲。","從身體的另一側投擲。"],"commonMistakes":["背得太遠，以至於下一次接球太晚了。","手臂在中間碰撞。"]},"penguin-cascade":{"name":"企鵝瀑布","description":"手臂垂直懸掛在兩側，手掌向下。每一次接球都發生在低處，向側面發生，拋球從臀部向上彈起。你看起來像一隻隨波逐流的企鵝。","goodFor":"手腕驅動的投擲和接球遠離通常的手部位置。","alignmentCues":["肘部伸直，雙手放在臀部。","從手腕輕彈，手掌朝後。"],"commonMistakes":["彎曲肘部回到正常的級聯。","向前拋擲，因為手腕翹起。"]},"under-the-leg":{"name":"腿下","description":"一個級聯，每六次投擲都在右腿下方。當球到達時抬起膝蓋，伸手到大腿下方並從外面嘔吐，然後放下腳進行下一次接球。","goodFor":"第一次身體丟擲：腿部提升和手臂伸展定時到一個節拍。","alignmentCues":["在投擲前抬起膝蓋，而不是在投擲過程中。","扔得更高一點，以覆蓋額外的觸及範圍。"],"commonMistakes":["向前彎曲到腿部，而不是抬起膝蓋。","腿放下後，衝向下一個投擲。"]},"behind-the-back":{"name":"倒背","description":"每六次投擲，右手在腰部後面擺動，將球扔到對肩上，將其降落在前面的圖案中。其他投擲保持正常級聯。","goodFor":"將盲人扔進你看不見的模式中。","alignmentCues":["當球落地時，儘早將手向後擺動。","瞄準遠側肩膀，比平時高一點。"],"commonMistakes":["向前扔得太遠，球落在你前面。","扭動整個軀幹。"]},"over-the-shoulder":{"name":"過肩拋","description":"每第六次投擲，右手將球從前方高高拋起，越過左肩後方。左手繞過臀部後方盲接，然後從臀部旁邊彈出下一個球。其餘動作均為普通瀑布式拋接。","goodFor":"盲接後背拋接，依靠感覺而非視覺來掌握時機。","alignmentCues":["拋球高度需足夠，能越過頭頂，剛好在左肩後方。","提前將接球手移至臀部後方，掌心向上。"],"commonMistakes":["轉頭尋找球。","拋球過低，導致球擦過頭部或肩膀。"]},"knee-bounce-cascade":{"name":"膝蓋彈球","description":"每第六次拋球時，右手趁右膝抬起把球放到膝上。球從大腿上方彈起，向上越過到左手，隨後腳放回地面，準備接下一個球。","goodFor":"單腿保持平衡，讓膝蓋在節拍上加入圖案。","alignmentCues":["抬膝迎球，大腿抬平。","讓球自然落下，不要往下扔。"],"commonMistakes":["用腳去踢球，結果球向前飛出。","彎腰去湊膝蓋，而不是把膝蓋抬高。"]},"head-bounce-cascade":{"name":"頭頂彈球","description":"每第六次拋球會從頭頂上方越過。頭向後仰，讓球落在額頭上，再點頭把球向下向前送進左手。其餘拋球照常在下方保持普通瀑布。","goodFor":"眼睛盯住頭頂正上方的球，雙手保持瀑布運轉。","alignmentCues":["提前仰頭，眼睛一直盯著球。","微微屈膝，讓彈跳更柔和。"],"commonMistakes":["用頭去頂球，而不是讓球落下來。","一抬頭，瀑布就亂了。"]},"crossed-arm-cascade":{"name":"交叉臂級聯","description":"交叉前臂，右手放在左側，並保持交叉。從那個位置玩弄一個級聯。即使圖案看起來正常，投擲也會感覺到映象。","goodFor":"打破每隻手生活的習慣。","alignmentCues":["將十字架放在手腕上，而不是肘部。","像往常一樣，投擲高峰出現在眼睛高度。"],"commonMistakes":["在投擲之間不交叉。","手在交換側面時碰撞。"]},"burkes-barrage":{"name":"伯克彈幕","description":"建立在423上。作為4投擲的球被抓住並帶過， 2是同一隻手中的短提升， 3被切成圖案。胳膊在忙碌中交織在一起。","goodFor":"在您熟悉的站點上組合爪子和爪子。","alignmentCues":["先學習423計時，然後新增進位。","2號幾乎沒有離開手。"],"commonMistakes":["把2扔得太高，打破了節奏。","忘記了3號線上的印章。"]},"rubensteins-revenge":{"name":"魯賓斯坦的復仇","description":"一串纏繞著52233。高投擲可以贏得時間，而雙手互相抓爪、切割和交叉，然後圖案放鬆回級聯。慢慢學習，一次一隻手。","goodFor":"火車攜帶的展示品，爪子和交叉的手臂在一起。","alignmentCues":["5是唯一的高投。","學習高球被淘汰的手步。"],"commonMistakes":["在搬運過程中驚慌失措，過早投擲。","高投飄向前方。"]},"siteswap-42":{"name":"雙球42","description":"兩個球：每隻手向自己投擲一個高球，並握住另一個球進行拍打。當雙手輪流時，高球在兩側成柱上升起。學習自我拋棄的安靜方式。","goodFor":"自擲4個高度，一手拼兩塊。","alignmentCues":["投擲者站在自己的一邊。","將2保持在手掌中。"],"commonMistakes":["拋擲飄過中間。","錯誤投擲持有的球。"]},"snake":{"name":"蛇","description":"三個球作為高高的橫跨五個，每個後面都有一個空的節拍。球沿著同樣的高弧一個接一個地延伸，就像一條蛇在你的頭上滑動。","goodFor":"始終如一的高投，沒有完整的五球節奏的壓力。","alignmentCues":["所有五個高度相同。","使用空拍來重置手。"],"commonMistakes":["五人向前漂移。","出於習慣而扔在空蕩蕩的節拍上。"]},"grace":{"name":"恩典（Grace）","description":"一個溫和的多重：一隻手同時投擲兩個球，一個正常的交叉投擲和一個直接傳給另一隻手的小傳球。然後保持節拍，回到瀑布。","goodFor":"從一隻手投擲兩個球的溫和介紹。","alignmentCues":["同時釋放兩個球。","小的幾乎沒有上升。"],"commonMistakes":["在不同時間釋放兩個球。","把小球扔得太高。"]},"orinoco-flow":{"name":"奧裡諾科之流","description":"兩輪42 ，末端縫合了級聯投擲，因此自投每次都會切換側面。它在柱子和級聯之間漣漪。","goodFor":"在自投和交叉投擲之間平穩切換。","alignmentCues":["在你身邊直立四下。","3是正常的級聯投擲。"],"commonMistakes":["四次向內傾斜。","失去五次投擲迴圈的計數。"]},"relfs-rhythm":{"name":"Relf的節奏","description":"一個自擲和一個持有，然後三級聯投擲。由於迴圈是奇怪的，每次自擲都會落在另一邊。","goodFor":"在兩側的跑步級聯中插入技巧。","alignmentCues":["先級聯，然後落入42。","讓這四個人站在自己的一邊。"],"commonMistakes":["只有在強壯的手上才能做到這一點。","之後，級聯加速。"]},"frostbite":{"name":"凍傷","description":"兩次快速四肢，快速穿過，然後兩次級聯投擲。通行證潛入下方，而四肢懸掛在頭頂上方。","goodFor":"在一個週期內將快速傳球與高投混合。","alignmentCues":["1是一個直截了當的閃爍。","四人保持垂直。"],"commonMistakes":["敲打1而不是傳遞它。","忘記第二個四個。"]},"siteswap-52512":{"name":"52512","description":"兩個高五被一個按住的節拍分開，然後是五，一個快速傳球和一個按住。該圖案將高位交叉投擲與短位低位投擲混合在一起。","goodFor":"三個球的精確高低控制。","alignmentCues":["五個都達到相同的高度。","手裡拿著兩個。"],"commonMistakes":["丟擲2s。","不均勻的五個。"]},"high-low-shower":{"name":"高低淋浴","description":"一個扭曲的淋浴：一個球非常高，而另一個球在下面快速地穿過低處。節奏聽起來像是賓士。","goodFor":"高度對比度大，雙手快速，三球圖案。","alignmentCues":["七人走得又高又直。","那些是平坦的通行證。"],"commonMistakes":["七人向前漂移。","電弧過高。"]},"siteswap-612":{"name":"612","description":"一個高大的自擲，一個快速通行證和一個擱置。六個球在你旁邊的同一邊上升，而另外兩個球在下面交換。","goodFor":"高自身投擲與快速低傳球混合。","alignmentCues":["這六個人站在它的一邊。","快速平穩地透過1。"],"commonMistakes":["六個交叉。","拿著2的時間太長。"]},"three-in-one":{"name":"三合一","description":"三個球在高柱或小噴泉中只用右手擺動。每次投擲都很高，所以有時間抓住並再次投擲。","goodFor":"單手控制和高度一致性。","alignmentCues":["投擲高峰遠高於頭部。","保持手在一個小圓圈內移動。"],"commonMistakes":["投擲向外漂移。","拋得太低，三球接不上。"]},"columns":{"name":"豎列","description":"三個球沿豎直的列上升。雙手同時丟擲各自外側的球，然後右手單獨丟擲中間那個。上、上、上，像活塞一樣。","goodFor":"第一次同時拋接，也是許多同步花式的基礎。","alignmentCues":["外側兩列同時向上。","中間一列從正中垂直向上。"],"commonMistakes":["列傾斜，球撞在一起。","成對丟擲的時機不齊。"]},"infinity":{"name":"無窮大","description":"一種豎列花式：單獨的那一拋不是直上，而是橫穿過去，中間的球每次都會換邊。球的軌跡呈8字形。","goodFor":"讓同步花式在兩側之間來回切換。","alignmentCues":["成對直上，單球橫穿。","每迴圈左右交替一次。"],"commonMistakes":["單球那一拋習慣性地直上。","成對的兩球漸漸漂移。"]},"rainbow-cross":{"name":"彩虹十字","description":"兩球成對交叉飛過，隨後一球從正中直上。交叉的弧線在你頭頂劃出一道彩虹。","goodFor":"同步交叉拋，互不相撞。","alignmentCues":["讓一個交叉拋稍微在另一個前方。","中間那一拋要直上。"],"commonMistakes":["交叉的兩球撞在一起。","中間那一拋歪了。"]},"crossunder":{"name":"下穿","description":"每一拋都交叉：先是一對交叉拋，再是一個單獨的交叉拋，每迴圈換一次邊。球在彼此上方與下方環繞穿行。","goodFor":"全交叉拋的同步控制。","alignmentCues":["讓各交叉拋處在略微不同的平面上。","全程高度一致。"],"commonMistakes":["球在中間相撞。","單球那一拋太短。"]},"yo-yo":{"name":"悠悠球","description":"一隻手拋豎列，另一隻手握著一個球，在其中一球的下方上下移動，彷彿兩個球被一根線連在一起。","goodFor":"一個錯覺花式，練習讓手中的球貼著豎列移動。","alignmentCues":["手中的球緊跟列上的球。","豎列保持垂直。"],"commonMistakes":["手中的球慢了半拍。","豎列漸漸散開。"]},"box":{"name":"方框","description":"球劃出一個方形。一隻手將球直上拋起，另一隻手同時將球橫傳過去，然後角色互換。兩側高，上下平。","goodFor":"一個經典的同步花式，訓練橫向傳球。","alignmentCues":["橫傳在齊手高度直線穿過。","縱拋筆直向上。"],"commonMistakes":["橫傳弧線太高。","柱式向內傾斜。"]},"broken-box":{"name":"破盒子","description":"一種每拋一次就換邊的盒式：縱拋和交叉橫傳輪流換手，方形因此不斷自我翻折。","goodFor":"同步節奏下的快速角色互換。","alignmentCues":["每一拍換一邊縱拋。","橫傳要平、要快。"],"commonMistakes":["縱拋總在同一側重複。","橫傳出手太急。"]},"als-slide":{"name":"阿爾的滑步","description":"一個交叉高拋配一個平橫傳，然後持球一拍，再來一個交叉高拋。球在上方和下方滑過，走出流暢的滾動軌跡。","goodFor":"同步交叉拋混合橫傳與持球。","alignmentCues":["交叉的4拋同時到頂。","把2穩穩握住不動。"],"commonMistakes":["把本該握住的球拋了出去。","球在中間撞在一起。"]},"factory":{"name":"工廠","description":"一隻手像傳送帶一樣，在腰部高度把球運到另一側；另一隻手則拋柱式。球像機器一樣迴圈運轉。","goodFor":"同步節奏下的運球與拋球配合。","alignmentCues":["運球的手畫出一個大圈。","垂直物保持高位。"],"commonMistakes":["將手丟球帶入柱中。","柱子傾斜。"]},"broken-shower":{"name":"損壞的淋浴間","description":"同步淋浴：右手高高跨過，而左手同時低低跨過。球繞成一個緊密的圈。","goodFor":"淋浴環路的同步版本。","alignmentCues":["雙手一起鬆開。","右側為高弧，左側為平通道。"],"commonMistakes":["一個接一個地釋放。","將電弧向上傳入高球。"]},"crossed-arm-shower":{"name":"交叉臂淋浴","description":"淋浴時，前臂交叉。高投來自身體的左側，快速投擲從下方返回。","goodFor":"淋浴控制在不熟悉的手臂位置。","alignmentCues":["在整個過程中保持交叉。","讓杖貼近身體傳遞。"],"commonMistakes":["解開交叉以便接杖。","傳遞過高。"]},"siteswap-534":{"name":"534","description":"一個混合交叉五拋、瀑布三拋與自拋四拋的四球花樣。手感像四球的423，還能順暢銜接噴泉。","goodFor":"最受歡迎的四球花式，也是通往更高階位換的入口。","alignmentCues":["五最高，三最低。","四留在自己那邊。"],"commonMistakes":["高度被壓平了。","三拋得太急。"]},"siteswap-552":{"name":"552","description":"兩個交叉的五加一個持球。四顆球以五球的節奏拋接，留出一拍呼吸。","goodFor":"丟擲五的高度，留有恢復時間。","alignmentCues":["兩個五完全相同。","把 2 穩穩持住。"],"commonMistakes":["把持球拋了出去。","五越拋越靠前。"]},"siteswap-5551":{"name":"5551","description":"連續三個五加一次快傳。通往五球瀑布的好跳板。","goodFor":"用四顆球練習連續的五。","alignmentCues":["所有五的高度一致。","1 要拋得又平又快。"],"commonMistakes":["五越來越低。","把 1 吊得太高。"]},"siteswap-55550":{"name":"55550","description":"四個五加一隻空手。相當於少一顆球的五球瀑布，因此是絕佳的五球預演。","goodFor":"五球瀑布前的最後一步。","alignmentCues":["利用空檔穩下來。","五保持穩定。"],"commonMistakes":["把球拋進了空檔。","五在漂移。"]},"siteswap-633":{"name":"633","description":"先一個高自拋，再接兩個瀑布拋。六懸在上方，瀑布在下方繼續。","goodFor":"把高自拋織入四球節奏。","alignmentCues":["六始終留在同側手的上方。","三保持低位。"],"commonMistakes":["六在橫向漂移。","三太高了。"]},"siteswap-53":{"name":"53","description":"一隻手拋高高的交叉五，另一隻手拋低低的瀑布三。四球的半淋浴。","goodFor":"兩手之間的高度控制。","alignmentCues":["右手高，左手低。","節奏均勻。"],"commonMistakes":["兩邊高度越來越接近。","三拋得太急了。"]},"wimpy":{"name":"Wimpy 花式","description":"四顆球，每一對都同時交叉。弧線每拍左右互換，形成大幅度的交叉穿梭。","goodFor":"四球的同步交叉。","alignmentCues":["有一隻手拋得稍微靠前。","同時出手。"],"commonMistakes":["球在中間相撞。","錯開出手時機。"]},"four-ball-shower":{"name":"四球洗澡式","description":"四球繞圈：一隻手丟擲極高的球，另一隻手在下方平快橫傳。","goodFor":"四球高拋的一致性。","alignmentCues":["7拋要直、要高。","橫傳要快、要平。"],"commonMistakes":["7拋在往前漂。","橫傳越拋越高。"]},"tsunami":{"name":"海嘯","description":"一個高高的7拋、一個停頓、一個自拋4、一個傳遞和一個高高的自拋6。高度如浪潮般在花樣中層層湧來。","goodFor":"四球混合高度的進階控制。","alignmentCues":["按順序放慢速度，逐個學會每個拋。","7和6都要拋高。"],"commonMistakes":["高度不穩定。","拍子數亂了。"]},"siteswap-645":{"name":"645","description":"534的五球版本：一個高高的自拋6、一個自拋4和一個交叉5。","goodFor":"從五球瀑布邁出的第一個花樣。","alignmentCues":["6拋要最高。","4留在自己這邊。"],"commonMistakes":["高度變平了。","球在漂移。"]},"siteswap-744":{"name":"744","description":"一個極高的交叉7拋，接著兩個自拋4。","goodFor":"在五球中插入高拋。","alignmentCues":["7拋又直又高。","4拋保持豎直。"],"commonMistakes":["7拋在漂移。","4拋在交叉。"]},"five-ball-shower":{"name":"五球洗澡式","description":"五球繞圈：一隻手丟擲高聳的9拋，另一隻手在下方平傳回來。","goodFor":"高度與精準的極限考驗。","alignmentCues":["9拋要直、要穩。","橫傳要平。"],"commonMistakes":["9拋在亂飄。","橫傳越拋越高。"]},"five-ball-half-shower":{"name":"五球半洗澡式","description":"五球同步交叉拋：一隻手拋得比另一隻高。","goodFor":"五球同步交叉的控制力。","alignmentCues":["右手高，左手低。","同時出手。"],"commonMistakes":["拋擲高度正在收攏。","碰撞。"]},"martins-one-count":{"name":"馬丁的圖案","description":"一個多重拋：高拋的6和一隻握住的球同時出手，然後是一個保持，再是一個交叉的5。","goodFor":"五球的多重拋時機。","alignmentCues":["多重丟擲手乾淨利落。","五個交叉拋。"],"commonMistakes":["拆分多重拋。","六球在漂移。"]},"six-ball-fountain":{"name":"六球噴泉","description":"每隻手三個球，並排丟擲高高的噴泉。","goodFor":"六球數字雜耍的里程碑。","alignmentCues":["每隻手各轉各的噴泉。","拋得又高又穩。"],"commonMistakes":["兩個噴泉一起漂移。","拋得太低。"]},"club-swing":{"name":"單棒單轉","description":"握住一根棒的棒柄，柄尾圓頭抵在掌根。從腰間向上揮起，讓它在空中轉一圈，棒柄先落入另一隻手。再用同樣的方式拋回去。","goodFor":"學習所有棒上花式的基礎——單轉。","alignmentCues":["從手肘發力上抬，讓手腕把棒翻過去。","在腰部高度接住棒柄。"],"commonMistakes":["手腕甩得太猛，棒會轉過頭。","向前拋，棒柄會落得太遠。"]},"club-exchange":{"name":"雙棒交換","description":"兩手各持一棒。右手丟擲一個單轉；在它到達頂點時，把左手的棒從其下方丟擲。兩根都接住棒柄，稍作停頓，再換另一隻手先拋。","goodFor":"掌握兩根旋轉棒的時機，避免相撞。","alignmentCues":["第二根棒踩著第一根的頂點出手。","從第一根棒的內側丟擲第二根。"],"commonMistakes":["棒在中間哐啷相撞。","兩隻手的轉速不一致。"]},"club-cascade":{"name":"三棒瀑布","description":"用棒拋的瀑布，每根轉一圈。拋擲從身體內側發出、橫向越過，棒柄始終朝向你。","goodFor":"所有棒上雜耍的基礎花式。","alignmentCues":["從手肘發力拋，手腕保持放鬆。","棒保持與胸口平行。"],"commonMistakes":["棒傾斜了，變成側向翻轉。","轉得太快，棒會打到身體。"]},"club-doubles":{"name":"雜耍棒雙轉","description":"三棒瀑布，每根棒在空中轉兩圈。拋得更高、更慢，棒在大圓圈裡轉出殘影。","goodFor":"旋轉控制，以及拋四根棒所需的高度。","alignmentCues":["多用手臂帶起來，而不是手腕。","讓雙轉平穩又均勻。"],"commonMistakes":["手腕甩得太猛，轉過了頭。","雙轉拋得太低。"]},"club-flats":{"name":"平棒","description":"一種棒完全不轉的瀑布拋接。每根棒柄朝下飄過，靠伸直的手腕向上推送，最後被豎直接住。","goodFor":"練手腕控制，也和旋轉拋接形成輕鬆對比。","alignmentCues":["鎖住手腕，用手肘推出去。","棒全程保持豎直。"],"commonMistakes":["不小心轉了半圈。","拋得太高，棒會晃。"]},"club-under-leg":{"name":"胯下拋棒","description":"用棒做的瀑布拋接，每第六個拋擲從右腿下穿過。抬起膝蓋，把棒從大腿下揮過去，讓它旋轉著升入模式中。","goodFor":"棒類的第一個身體拋。","alignmentCues":["膝蓋早點抬起來。","腿下那拋稍微加一點高度。"],"commonMistakes":["棒打到腿。","彎腰俯身，而不是抬膝。"]},"club-behind-back":{"name":"背後拋棒","description":"用棒做的瀑布拋接，每第六個拋擲在腰後揮出，越過另一側肩膀送回模式中。","goodFor":"在身後盲區拋棒。","alignmentCues":["手臂早點繞到身後。","瞄準另一側肩的上方。"],"commonMistakes":["棒落得太靠前。","上身扭轉。"]},"club-four-fountain":{"name":"四棒噴泉","description":"雙手各持兩棒，每隻手在自己的噴泉裡拋雙轉。棒從不越過中線。","goodFor":"四棒里程碑。","alignmentCues":["雙轉留在各自一側。","雙手均勻交替。"],"commonMistakes":["棒漸漸飄向中間。","兩手轉得不均勻。"]},"ring-cascade":{"name":"三圈瀑布","description":"一種瀑布拋接，圈側立持握，就像從側面看去的方向盤。每個圈不翻轉地飛過整個模式，邊緣利落地切開空氣。","goodFor":"入門圈的簡單方法，感受它們飄浮的感覺。","alignmentCues":["把圈側立對著自己。","出手時手腕保持平直。"],"commonMistakes":["手腕翹起，圈就晃。","圈面朝前拋，容易兜風。"]},"ring-pancakes":{"name":"戒指煎餅","description":"一種圈的瀑布拋接：每個圈在拋到最高點時翻平，接住時又轉回側立，就像鍋裡翻煎餅一樣。","goodFor":"手腕控制，外加炫目的圈花式。","alignmentCues":["出手時手腕快速一轉。","再次側立著接圈。"],"commonMistakes":["翻轉過度。","拋得太低，圈來不及翻轉。"]},"ring-four-fountain":{"name":"四圈噴泉","description":"每隻手兩個圈，各自做獨立的噴泉式，圈側立著直上直下。","goodFor":"四個物體，道具輕盈飄逸。","alignmentCues":["圈始終保持側立。","每隻手各走各的豎線。"],"commonMistakes":["圈在中間相碰。","圈越拋越靠前。"]},"hoop-juggle-single":{"name":"單呼啦圈拋接","description":"手握呼啦圈邊緣，讓它垂在身側。用柔和的弧線把它拋向另一隻手，讓它全程側立飛行，落回出手時的高度。","goodFor":"先學會一隻全尺寸呼啦圈怎麼飛，再考慮加圈。","alignmentCues":["讓呼啦圈側立，正對你的胸口。","用肩膀發力拋，而不是手腕。"],"commonMistakes":["拋成了正面朝前，呼啦圈飄走了。","拋得太低，還伸手去抓。"]},"hoop-juggle-exchange":{"name":"雙呼啦圈交換","description":"每隻手一個呼啦圈。先拋右手的圈；等它到最高點時，從下面丟擲左手的圈。兩個圈近距離交錯，一前一後。","goodFor":"掌握雙圈時機，避免兩圈相撞。","alignmentCues":["第二個圈在第一個圈的頂點出手。","把第二個圈稍微拋得靠前一點。"],"commonMistakes":["兩個圈互相碰撞。","兩個圈都拋得太快。"]},"hoop-juggle-cascade":{"name":"三呼啦圈瀑布","description":"用全尺寸呼啦圈玩的瀑布式。雙手保持較寬的間距，拋得又高又慢，每個呼啦圈全程側立翻轉。","goodFor":"呼啦圈拋接的基礎花樣。","alignmentCues":["雙臂張開，手肘放鬆。","所有呼啦圈都在同一個平面上。"],"commonMistakes":["呼啦圈越拋越靠前。","拋得太急。"]},"hoop-juggle-reverse":{"name":"反向呼啦圈瀑布","description":"呼啦圈從外側越過頂端丟擲，在內側接住——放大版的反向瀑布。","goodFor":"用呼啦圈做外側拋。","alignmentCues":["從外側拋，越過頂端。","在靠近中間的位置接住。"],"commonMistakes":["呼啦圈落點太靠外。","弧線不均勻。"]},"hoop-juggle-shower":{"name":"圈淋浴","description":"三個圈走環形：一隻手高拋，另一隻手在下方快速交接回傳。","goodFor":"圈的拋高與傳遞控制。","alignmentCues":["高拋直上，橫向越過。","傳遞貼近身體。"],"commonMistakes":["高拋跑偏了。","傳遞偏高。"]},"hoop-juggle-two-in-one":{"name":"單手雙圈","description":"只用右手拋接兩個圈，讓它們在身側呈縱列上升。","goodFor":"單手控圈。","alignmentCues":["縱列保持垂直。","拋高，爭取時間。"],"commonMistakes":["圈往外跑了。","太低了。"]},"hoop-juggle-423":{"name":"圈 423","description":"三個圈的 423 位換：一個自拋的 4、一個持住的 2 和一個交叉的 3。","goodFor":"圈的位換變化。","alignmentCues":["4 留在自己那一側。","持住 2。"],"commonMistakes":["把 2 丟擲去了。","4 往對面跑了。"]},"hoop-juggle-441":{"name":"圈 441","description":"用圈做兩個自拋 4 加一次快速交接。交接從高拋的一對圈下方滑過。","goodFor":"在高拋的圈之間快速交接。","alignmentCues":["4 保持豎直。","交接要平。"],"commonMistakes":["交接拋高了。","4 跑偏了。"]},"hoop-juggle-four":{"name":"四圈噴泉","description":"每隻手兩個圈，左右並排做噴泉式拋接。","goodFor":"四圈的里程碑。","alignmentCues":["兩邊各自獨立。","節奏均勻。"],"commonMistakes":["圈一起跑偏了。","拋得太低。"]},"hoop-juggle-under-leg":{"name":"腿下拋圈","description":"圈的瀑布式拋接，每第六拋從抬起的右腿下方穿過。","goodFor":"用大道具練習身體拋。","alignmentCues":["膝蓋抬高。","拋得再高一點。"],"commonMistakes":["圈碰到腳了。","身體前傾。"]},"hoop-juggle-back-throw":{"name":"圈背後拋","description":"一種圈的瀑布式拋接：每第六拋從背後越過遠側肩丟擲。","goodFor":"圈的盲拋。","alignmentCues":["提早擺到背後。","越過遠側肩。"],"commonMistakes":["圈落在身前。","轉體。"]},"hoop-juggle-body-hoop":{"name":"邊轉腰圈邊拋接","description":"讓一個圈在腰上持續旋轉，同時用另外三個圈做瀑布式拋接。髖部在手臂下方保持自己的節奏。","goodFor":"在轉圈和拋接之間分配注意力。","alignmentCues":["髖部驅動腰上的圈，手臂保持獨立。","讓拋接平面保持在腰圈前方。"],"commonMistakes":["專注拋接時，腰上的圈慢了下來。","手臂垂進了腰圈的軌跡。"]},"pass-one-ball":{"name":"一球通","description":"站在您的伴侶面前，相距約2.5米。從右手向左手輕輕丟擲一個球。他們把它交給他們的右邊，然後把它扔回你的左邊，然後你再把它交給你的右邊。","goodFor":"在雜耍之前學習傳球的高度和距離。","alignmentCues":["直接扔過去，不要越界。","山峰就在頭部高度之上，在你們中間。","看看你的搭檔，而不是你手中的球。"],"commonMistakes":["扔在伴侶的臉上，而不是豎起弧線。","瞄準他們的右手，所以傳球交叉。"]},"pass-hand-across":{"name":"雙球傳球","description":"每人兩個球，你們兩個都從右邊以同樣的節拍傳球。每隻左手抓住傳入的通行證，並將其直接遞到右側，為下一個通行證做好準備。沒有任何東西會被扔給自己，所以這一切都與傳球的時間有關。","goodFor":"在新增級聯之前傳遞共享節拍。","alignmentCues":["一起傳遞：右手放在計數器上。","用左手抓住，手跨過低處並快速抓住。"],"commonMistakes":["你們中的一個提前經過，所以通行證在不同的時間在空中交叉。","把手扔向對面，而不是遞給對方。"]},"pass-six-count":{"name":"六拍","description":"你們倆玩弄一個三球級聯，每六投一次，總是從右手傳到伴侶的左手。在傳球之間，您有五次自擲來確定模式。","goodFor":"第一個完整的傳球模式：傳球之間有充足的時間。","alignmentCues":["大聲數：傳球，二，三，四，五，六。","保持您的自我與通行證的高度相同。","看看你的伴侶，而不是你自己的手。"],"commonMistakes":["失去計數並傳遞錯誤的節拍。","透過短路，所以你的伴侶不得不猛衝。"]},"pass-four-count":{"name":"四拍","description":"每四次投擲，每隔一次右手投擲。透過、自我、自我、自我，然後再次透過。這是標準的球杆熱身，也是大多數變體的基礎。","goodFor":"日常傳球模式；大多數技巧都從這裡開始。","alignmentCues":["右手合在一起。","三個自己，然後傳球又來了。"],"commonMistakes":["摺疊自我，為通行證騰出時間。","轉動肩膀投擲，而不是使用前臂。"]},"pass-three-count":{"name":"三拍","description":"每三次投擲傳球，傳球交替進行：向右，然後向左，然後向右。每次左側通行證都會直接穿過伴侶的右手。","goodFor":"雙手傳球，雙手接球。","alignmentCues":["左邊的傳球直接穿過，就像右邊一樣。","雙手保持傳球高度不變。"],"commonMistakes":["一個弱的左手傳球，傳得很短。","穿過左邊傳遞給他們的左手。"]},"pass-two-count":{"name":"兩拍","description":"每次右手投擲都是一次傳球，每次左手投擲都是一次自我。通行證、自我、通行證、自我。以相同的步法，傳球次數是四次傳球次數的兩倍。","goodFor":"快速，甚至傳遞節奏；通往七種物件模式的門戶。","alignmentCues":["右手過去，左手過去。","將左側自我保持在傳入通行證下方。"],"commonMistakes":["讓自我變得越來越低。","捕捉通道過於靠近身體。"]},"pass-left-two-count":{"name":"左手雙計數","description":"雙計數映象：每次左手投擲都是傳球，直接穿過伴侶的右手，右手投擲自己。","goodFor":"使你較弱的傳球手平靜下來。","alignmentCues":["左側直接穿過，而不是穿過。","與右手透過時的高度和推力相同。"],"commonMistakes":["從虛弱的手中短路。","習慣性地切換回右手。"]},"pass-ultimates":{"name":"終極動作","description":"每一次投擲都是一次傳球。右手直接穿過左手，左手直接穿過右手；沒有人投擲自己。球在你們之間不斷湧動。","goodFor":"在壓力下傳遞準確性和節奏。","alignmentCues":["每次投擲都會穿過：右側、左側、右側、左側。","抓住並傳入一個流動的鏟子。"],"commonMistakes":["拿著球打破溪流。","隨著節奏的上升而變得更加平坦。"]},"club-pass-four-count":{"name":"棒四拍","description":"帶棍棒的四支球杆。每次傳球都是從右手向伴侶的左手投擲的單次旋轉，首先到達手柄。傳球之間有三個單一的自我。","goodFor":"每次俱樂部傳球的標準開局。","alignmentCues":["從右臀部旁邊傳遞，直線向前擺動。","一次旋轉：手柄應落在伴侶的手中。"],"commonMistakes":["過度旋轉，因此傳球首先到達旋鈕。","穿過身體到達伴侶的右側。"]},"club-pass-two-count":{"name":"棒兩拍","description":"每次右手投擲都是一次傳球，每次左手投擲都是一次自我。俱樂部傳球的核心節奏。","goodFor":"穩定的球杆傳球節奏。","alignmentCues":["PASS、SELF、PASS、SELF、ON EVEN BEAT","保持左側自身繃緊並保持在室內。"],"commonMistakes":["將旋轉落在左側自身上。","透過左右徘徊。"]},"club-pass-three-count":{"name":"棒三拍","description":"俱樂部每三次投擲都會傳球，因此他們會輪流投擲。左側通行證直接穿過伴侶的右側。","goodFor":"球杆從弱者手中傳出。","alignmentCues":["雙手同樣的揮杆。","向右，然後向左，然後向右：數出來。"],"commonMistakes":["左手傳球旋轉太少。","將車身轉向左側通行證。"]},"club-pass-doubles":{"name":"帶雙人床的Club Four-Count","description":"一種四拍模式：每次傳遞都是雙旋，拋得更高，因此晚一拍才落下。為了騰出時間，傳遞後左手握棒多停一拍，不做自拋。","goodFor":"雙旋傳遞，邁向七棒傳遞的第一步。","alignmentCues":["雙旋傳遞更高、更慢：棒要轉滿整整兩圈。","傳遞時握住左棒不拋，然後照常繼續。"],"commonMistakes":["把雙旋拋得像單旋一樣快，棒就會轉過頭。","把左棒拋了出去，而不是握住。"]},"club-pass-ultimates":{"name":"棒Ultimates","description":"每次拋擲都是單旋傳遞，左右手交替。六根棒在兩人之間川流不息，完全沒有自拋。","goodFor":"全速傳棒的精準度。","alignmentCues":["接棒即傳，一揮完成。","直線傳遞：右到左，左到右。"],"commonMistakes":["傳遞飄向中間，互相碰撞。","握棒不拋，打斷了流動。"]},"club-pass-seven-doubles":{"name":"七棒交叉雙旋","description":"你們之間共有七根棒。你的右手每隔一次拋擲，就向同伴的右手傳出一個交叉雙旋；一拋之後，對方的左手回傳一個交叉雙旋到你的左手。空檔由單旋填補。","goodFor":"第一個七棒模式，以雙旋為基礎。","alignmentCues":["你的雙旋交叉飛向同伴的右手。","自己剛傳完，就用左手接住對方的雙旋。"],"commonMistakes":["傳成了直線，而不是交叉。","雙旋太低，轉不滿兩圈。"]},"staff-wheel-spin":{"name":"雙手輪轉","description":"雙手掌心向下，在胸口高度握住杖的中間。在身體一側像輪子一樣轉動，讓旋轉在兩手之間傳遞，保持杖在身體旁邊。","goodFor":"第一個杖旋轉；建立握力和手腕旋轉。","alignmentCues":["杖始終與身體平行，絕不傾斜。","輕柔握持：讓它從指間滾過。"],"props":["棍"],"commonMistakes":["握得太緊導致旋轉停滯。","將平面向前傾斜。"]},"staff-front-spin":{"name":"正面風車","description":"在牆平面中像螺旋槳一樣在身前旋轉杖，圍繞其中心在兩手之間順暢傳遞。","goodFor":"加入牆平面和手過手的傳遞。","props":["棍"]},"staff-figure-8":{"name":"8字編織","description":"在輪平面中於右側旋轉杖，然後交叉到左側並在那裡旋轉，在身前描繪一個8字。","goodFor":"連線身體兩側；staff flow的骨幹。","alignmentCues":["當杖尖經過地面時切換側邊。","每換一側時軀幹稍微旋轉。"],"props":["棍"]},"staff-pass-through":{"name":"穿手傳遞","description":"在牆平面中旋轉，但每半圈就鬆手：一隻手釋放杖，另一隻手在中心接住，讓杖在兩手之間穿過。","goodFor":"教授釋放和接住的時機。","props":["棍"]},"staff-one-hand-spin":{"name":"單手旋轉","description":"用一隻手在身前旋轉杖，讓它滾過手背並穿過手指。雙手都要練習。","goodFor":"手指和手腕力量；解放另一隻手做技巧。","props":["棍"]},"staff-helicopter":{"name":"頭頂直升機","description":"將杖舉過頭頂，用一隻手在地平面中平轉，像直升機葉片一樣。","goodFor":"引入地平面。","props":["棍"]},"staff-butterfly":{"name":"蝴蝶","description":"在身前旋轉，然後將杖折到肩後並再折出，每側前後交替，像翅膀一樣。","goodFor":"肩部靈活性以及流暢的前後轉換。","props":["棍"]},"staff-behind-back-pass":{"name":"背後傳遞","description":"在旋轉的最低點於背後將旋轉中的杖從一隻手傳到另一隻手，然後把它繞回身前。","goodFor":"身體纏繞和展示性傳遞。","props":["棍"]},"staff-isolation":{"name":"棍隔離","description":"握住棍的一端附近，用手繞著棍的中心畫圓，讓中心看起來固定在空氣中，而棍圍繞它旋轉。","goodFor":"幻象技巧和精準的手部軌跡。","props":["棍"]},"staff-antispin-flower":{"name":"四瓣反旋","description":"手朝一個方向畫圓，同時棍以三倍速度朝反方向旋轉，讓棍畫出一朵四瓣花。","goodFor":"VTG標誌性花朵；深度節奏控制。","props":["棍"]},"staff-neck-roll":{"name":"頸部滾動","description":"將棍放到肩背上，讓它沿頸部滾到另一隻手。先用軟包棍慢慢練習。","goodFor":"接觸棍：棍在身體上移動，不靠手。","avoidIf":["頸部疼痛。"],"props":["棍"]},"staff-reverse-wheel":{"name":"反向車輪旋轉","description":"車輪旋轉的反向版本：棍的前端升起，越過頂端繞回。雙手仍握在中段，像正轉一樣把它滾過去。","goodFor":"平衡兩個旋轉方向，讓之後的每個動作正反都能做。","alignmentCues":["還是身側那個平面的車輪，只是方向變了。","讓指關節先向後滾，帶動旋轉。"],"props":["長棍"],"commonMistakes":["旋轉平面漂移過身體。","不知不覺又轉回正轉。"]},"staff-reverse-front-spin":{"name":"反向前旋","description":"雙手前旋的反方向版本：上端向你的右側落下，而不是左側。","goodFor":"先掌握前旋的兩個方向，再學傳遞或編織。","alignmentCues":["讓棍端平，正對胸前。","雙手交換的方式不變，只是方向反過來。"],"props":["長棍"],"commonMistakes":["棍端朝你傾倒。","換手時節奏亂了。"]},"staff-one-hand-wheel":{"name":"單手車輪旋轉","description":"只用一隻手在身側的車輪平面轉棍，讓它滾過手背、穿過手指。","goodFor":"身側的單手控制：車輪定點旋轉與雙棍的基礎。","alignmentCues":["棍從髖部外側剛好經過。","手肘貼近肋側。"],"props":["長棍"],"commonMistakes":["棍端碰到腿了。","手腕鎖死了。"]},"staff-wheel-pass":{"name":"輪面換手","description":"一種輪面旋轉，每半圈換一次手。一隻手趁棍子呈水平時接住，帶著它轉半圈，再交給另一隻手。","goodFor":"在身側流暢換手。","alignmentCues":["趁棍子水平時接住。","空手在近處隨時接應。"],"props":["長棍"],"commonMistakes":["棍子還沒到水平就急著抓。","每次換手，平面就跑偏。"]},"staff-two-hand-helicopter":{"name":"雙手直升機","description":"棍子在頭頂上方平轉，雙手都握在棍上，一隻手像旋翼一樣從另一隻手上方越過。","goodFor":"輕鬆初識地面平面。","alignmentCues":["手臂放鬆，棍子略高於頭頂。","雙手在臉前交換。"],"props":["長棍"],"commonMistakes":["棍子向前傾。","聳肩了。"]},"staff-overhead-pass":{"name":"頭頂換手","description":"直升機在頭頂上方換手傳遞，每隻手帶著棍子轉半圈。","goodFor":"在地面平面內換手。","alignmentCues":["趁棍子指向前後方時換手。","手肘保持放鬆。"],"props":["長棍"],"commonMistakes":["棍子掉到腦後。","抓得太早。"]},"staff-one-hand-reverse":{"name":"單手反轉","description":"單手正轉的反向版本，先朝拇指一側翻過去。","goodFor":"單手雙向都能控制。","alignmentCues":["同一平面，同樣速度，方向相反。","棍子滾動時，手指保持放鬆。"],"props":["長棍"],"commonMistakes":["手腕繃緊了。","半圈轉速變慢。"]},"staff-reverse-helicopter":{"name":"反向直升機","description":"頭頂上方的單手直升機，朝相反方向轉。","goodFor":"頭頂上方，兩個方向都掌握。","alignmentCues":["棍身像旋翼一樣保持水平。","手保持在額頭上方。"],"props":["長棍"],"commonMistakes":["向前傾斜了。","手臂完全伸直。"]},"staff-extension":{"name":"延伸","description":"握住長棍靠近一端的位置，讓它繞著手掃出一個大圓，手幾乎不動。遠端在你身前畫出一個大圓環。","goodFor":"定點旋轉所需的大幅圖形與手腕滾動。","alignmentCues":["手是圓的軸心。","轉動手腕，不要揮動手臂。"],"props":["長棍"],"commonMistakes":["靠肩膀揮動。","圓圈被壓扁成橢圓。"]},"staff-wheel-extension":{"name":"輪式延伸","description":"身側的延伸：長棍在髖部高度繞手掃出一個大輪。","goodFor":"輪平面上的大圓。","alignmentCues":["讓圓保持在腿外側。","手腕轉動，手臂保持不動。"],"props":["長棍"],"commonMistakes":["掃到腳。","身體向遠離長棍的方向傾斜。"]},"staff-floor-extension":{"name":"頭頂延伸","description":"頭頂上方的水平延伸：長棍繞著高舉的手掃動，像一根長長的旋翼槳葉。","goodFor":"頭頂伸展能力與搶眼的地平面圖形。","alignmentCues":["手舉在頭頂上方。","棍身保持水平。"],"props":["長棍"],"commonMistakes":["長棍在身後下沉。","手臂向前偏移。"]},"staff-wheel-isolation":{"name":"輪式定點旋轉","description":"身側的定點旋轉：長棍中心保持固定，手繞著它畫圈。","goodFor":"在另一平面上的定點控制。","alignmentCues":["在髖部旁邊選一個點作為中心。","手沿小圓移動。"],"props":["長棍"],"commonMistakes":["中心點遊移。","平面傾斜。"]},"staff-floor-isolation":{"name":"頭頂定點旋轉","description":"頭頂上方的水平定點旋轉：手畫圈時，長棍繞著一個固定點轉動。","goodFor":"頭頂定點旋轉。","alignmentCues":["固定點在你頭頂上方。","手畫小圈。"],"props":["長棍"],"commonMistakes":["中心點漂移。","手圈逐漸放大。"]},"staff-isolation-pass":{"name":"隔離交接","description":"每半圈在雙手之間交接一次隔離，定點保持不動，雙手互相交換。","goodFor":"雙手隔離控制。","alignmentCues":["在圓圈底部交接。","交接過程中保持中心固定。"],"props":["杖"],"commonMistakes":["交接時中心跳動。","雙手相撞。"]},"staff-antispin-3":{"name":"三瓣反旋","description":"手朝一個方向畫圈，杖朝反方向旋轉，畫出一朵三瓣的花。","goodFor":"第一個反旋花。","alignmentCues":["手圈要慢而圓。","杖朝反方向旋轉。"],"props":["杖"],"commonMistakes":["花瓣不均勻。","手圈走形。"]},"staff-antispin-5":{"name":"五瓣反旋","description":"更精細的五瓣反旋花，手要更慢地逆著旋轉畫圈。","goodFor":"反旋時機要精準。","alignmentCues":["數一數花瓣。","手要慢慢移動。"],"props":["杖"],"commonMistakes":["花瓣粘連。","手部太急。"]},"staff-wheel-antispin":{"name":"輪面反旋","description":"在身體側面的輪面上畫出的反旋花。","goodFor":"在第二個平面畫花。","alignmentCues":["豎直平面。","花瓣均勻。"],"props":["杖"],"commonMistakes":["平面傾斜。","花瓣向前漂移。"]},"staff-floor-antispin":{"name":"頭頂反旋","description":"在頭頂上方水平畫出的反旋花。","goodFor":"頭頂上方的花。","alignmentCues":["水平平面。","手舉過頭頂。"],"props":["杖"],"commonMistakes":["傾斜了。","花瓣不均勻。"]},"staff-inspin-3":{"name":"三瓣內旋","description":"手沿旋轉方向畫圈，但速度更慢，長棍就會畫出三個朝內的花瓣。","goodFor":"最柔和易學的花型。","alignmentCues":["手和長棍同向轉動。","手畫圈要大而慢。"],"props":["長棍"],"commonMistakes":["手加速跟上長棍。","花瓣歪斜。"]},"staff-inspin-4":{"name":"四瓣內旋","description":"一種帶四個朝內花瓣的內旋花。","goodFor":"更進一步的內旋控制。","alignmentCues":["數出四個花瓣。","手要穩。"],"props":["長棍"],"commonMistakes":["花瓣粘連。","手在漂移。"]},"staff-wheel-inspin":{"name":"車輪內旋","description":"在身體側面畫出的三瓣內旋。","goodFor":"車輪平面上的內旋。","alignmentCues":["平面保持豎直。","手放慢。"],"props":["長棍"],"commonMistakes":["傾斜了。","擦到腿了。"]},"staff-reverse-figure-8":{"name":"反向8字","description":"把8字反過來轉：長棍在身前升起，在兩側落到身後。","goodFor":"編織的兩個方向。","alignmentCues":["在身前交叉。","每一側保持豎直。"],"props":["長棍"],"commonMistakes":["交叉時平面塌掉。","軀幹僵硬。"]},"staff-front-weave":{"name":"正面編織","description":"一種正面旋轉，每轉一圈便從身體一側漂移到另一側，胸口隨之轉動。","goodFor":"讓旋轉橫穿身體。","alignmentCues":["胸口跟著長棍轉。","旋轉始終正對著你。"],"props":["長棍"],"commonMistakes":["腳也跟著轉了。","交叉時平面傾斜。"]},"staff-overhead-weave":{"name":"頭頂編織","description":"一種雙手直升機動作，每轉一圈便從頭部一側擺向另一側。","goodFor":"在地面平面編織。","alignmentCues":["全程保持兩端水平。","軀幹隨棍轉動。"],"props":["長棍"],"commonMistakes":["一側下沉。","頭部擋住了去路。"]},"staff-fountain":{"name":"噴泉","description":"輪平面中的分拍編織：兩端像噴泉的水花，在兩側交替向上噴出、翻過。","goodFor":"在身側保持分拍。","alignmentCues":["兩端在兩側交替升起。","交叉要快。"],"props":["長棍"],"commonMistakes":["動作塌成了普通8字。","平面傾斜。"]},"staff-reel":{"name":"捲筒","description":"每次交叉都換手的8字動作，棍子像卷線一樣從一側繞到另一側。","goodFor":"把編織和傳遞結合起來。","alignmentCues":["在交叉處傳遞。","每一側都保持豎直。"],"props":["長棍"],"commonMistakes":["抓握過早。","軀幹僵硬。"]},"staff-wall-wheel-hybrid":{"name":"牆面-輪面混合","description":"每轉一圈，旋轉就在身前的牆面與身旁的輪平面之間切換，趁棍子豎直時換面。","goodFor":"換面不停頓。","alignmentCues":["棍子豎直朝上時切換。","手腕轉四分之一圈。"],"props":["長棍"],"commonMistakes":["在水平位置切換。","切換時掉速。"]},"staff-floor-wall-hybrid":{"name":"牆面-地面混合","description":"旋轉在身前與頭頂之間交替，每當棍子呈水平時切換。","goodFor":"把正面旋轉和直升機連起來。","alignmentCues":["在水平位置切換。","流暢地抬起手臂。"],"props":["長棍"],"commonMistakes":["在豎直時切換。","肘部鎖死。"]},"staff-floor-wheel-hybrid":{"name":"地面-車輪混合式","description":"直升機動作：每轉一圈，杖就落到身旁變成車輪，再升回直升機。","goodFor":"完整的平面轉換組合。","alignmentCues":["手臂平穩地抬起、放下。","平面乾淨利落。"],"props":["杖"],"commonMistakes":["中間平面模糊。","速度在下降。"]},"staff-under-leg-pass":{"name":"胯下傳杖","description":"一種穿傳花樣：每隔一次傳遞，就從抬起的右腿下方穿過。","goodFor":"在傳杖動作中加入腿部動作。","alignmentCues":["將膝蓋抬高至道具處。","在髖部摺疊，背部伸展，坐入站立的膝蓋。","當道具越過腿部時，重新站起。"],"props":["杖"],"commonMistakes":["背部彎曲以夠到道具，而不是在髖部摺疊。","膝蓋位置過低，導致道具必須從下方穿過。","急於將道具從腿下穿過。"]},"staff-reverse-behind-back":{"name":"反向背後傳杖","description":"背後傳杖沿身體另一方向繞行，旋轉方向也相反。","goodFor":"讓杖繞身體雙向執行。","alignmentCues":["身後的手放低等待。","讓背後的旋轉持續不斷。"],"props":["杖"],"commonMistakes":["背後的平面跑偏。","旋轉停住。"]},"staff-fishtail":{"name":"魚尾","description":"杖在攤開的手掌上像魚兒擺尾一樣來回搖擺，始終差一點沒能完整轉過去。","goodFor":"攤掌控制與改變旋轉方向。","alignmentCues":["以拇指和手指為支點轉動。","手腕輕輕一抖就能反轉擺動。"],"props":["杖"],"commonMistakes":["握得太緊。","擺幅越來越大。"]},"staff-wheel-fishtail":{"name":"輪平面魚尾","description":"在身體一側的輪平面內做魚尾。","goodFor":"在第二個平面做魚尾。","alignmentCues":["豎直平面。","張開手掌。"],"props":["長棍"],"commonMistakes":["棍身傾斜。","抓握。"]},"staff-steering-wheel":{"name":"方向盤","description":"雙手掌心攤平，交替轉動棍子，就像在身前轉動一個大方向盤。","goodFor":"雙手放鬆，掌心攤平接觸。","alignmentCues":["掌心攤平，手指放鬆。","在頂端雙手交替。"],"props":["長棍"],"commonMistakes":["抓握而非引導。","手肘外張。"]},"staff-palm-spin":{"name":"掌心轉棍","description":"把棍子中段平衡在抬平的掌心上，讓它像螺旋槳一樣在那裡旋轉。","goodFor":"頭頂保持平衡，輕輕接觸。","alignmentCues":["掌心攤平，保持水平。","畫小圈讓它持續轉動。"],"props":["長棍"],"commonMistakes":["掌心傾斜。","用力推而非輕撥。"]},"staff-hand-roll":{"name":"手背滾棍","description":"棍子從攤開的手背上滾過、繞過拇指，全程不用抓握。","goodFor":"第一個真正的接觸式滾轉。","alignmentCues":["手攤開、放鬆。","讓棍子自己完成動作。"],"props":["長棍"],"commonMistakes":["手指收攏。","手部動作太多。"]},"staff-forearm-roll":{"name":"前臂滾棍","description":"把旋轉釋放到前臂上，讓棍子在前臂上轉過去，再接回手中繼續旋轉。","goodFor":"把旋轉移到手臂上再接回來。","alignmentCues":["前臂保持水平、穩定。","棍子落下時張開手。"],"props":["長棍"],"commonMistakes":["前臂傾斜。","抓得太早。"]},"staff-elbow-roll":{"name":"肘彎滾棍","description":"旋轉移到彎曲的肘彎裡，抬著手在那裡繼續轉動，然後再回到手上。","goodFor":"進階的接觸式控制。","alignmentCues":["前臂保持豎直。","手肘保持不動。"],"props":["長棍"],"commonMistakes":["手肘下垂。","短棍滑脫了。"]},"staff-shoulder-roll":{"name":"肩滾","description":"將車輪轉抬上肩頭，讓棍在頭旁繼續轉動，隨後落回手中。","goodFor":"在身體高處做接觸滾轉。","alignmentCues":["肩膀微微抬起。","頭微微偏開。"],"props":["短棍"],"commonMistakes":["頭擋住了。","肩膀在下沉。"]},"staff-chest-roll":{"name":"胸滾","description":"短棍保持水平，從一隻手沿胸前滾到另一隻手，再滾回來。","goodFor":"棍貼身前滾動。","alignmentCues":["挺起胸口。","棍保持水平。"],"props":["短棍"],"commonMistakes":["胸口塌下來了。","棍在傾斜。"]},"staff-angel-roll":{"name":"天使滾","description":"雙臂大大張開，短棍滾過肩後，再沿雙臂從一隻手滾到另一隻手。","goodFor":"很有觀賞性的接觸滾轉。","alignmentCues":["雙臂放平，掌心向上。","夾緊肩胛骨。"],"props":["短棍"],"commonMistakes":["手臂在下沉。","頭往前伸了。"]},"staff-toss":{"name":"拋棍","description":"在水平位置鬆手放出單手旋轉，讓棍在空中轉一圈，再接回同樣的旋轉。","goodFor":"丟擲並接住旋轉中的短棍。","alignmentCues":["棍到水平時鬆手。","接在棍的中段。"],"props":["短棍"],"commonMistakes":["向前拋了。","接到了棍端。"]},"staff-double-toss":{"name":"雙轉拋","description":"拋得更高，接住前在空中完整轉兩圈。","goodFor":"控制空中的高度與轉速。","alignmentCues":["拋得更高，轉速不變。","眼睛盯住中段。"],"props":["短棍"],"commonMistakes":["轉速給多了。","向前漂移。"]},"staff-flat-toss":{"name":"平拋","description":"把直升機垂直向上丟擲，讓它在空中轉平，然後在頭頂上方接住。","goodFor":"在水平面內丟擲。","alignmentCues":["出手時保持水平。","在頭頂上方接住。"],"props":["長棍"],"commonMistakes":["出手時傾斜。","拋向身後。"]},"double-staff-same-time":{"name":"雙棍同拍","description":"雙手各持一根短棍，兩根棍在身前同向同拍旋轉。","goodFor":"雙棍入門第一式。","alignmentCues":["兩棍並排，一根略微靠前。","雙手速度一致。"],"props":["兩根短棍"],"commonMistakes":["兩棍相撞。","一隻手跟不上。"]},"double-staff-split-time":{"name":"雙棍分拍","description":"兩根棍同向旋轉，但其中一根落後四分之一圈，於是一根豎直時，另一根正好水平。","goodFor":"雙手節奏各自獨立。","alignmentCues":["一根豎直，一根水平。","錯位保持穩定。"],"props":["兩根短棍"],"commonMistakes":["不小心變回同拍。","相撞。"]},"double-staff-wheels":{"name":"雙棍輪轉","description":"身體兩側各做一個輪轉，兩根同時向前轉。","goodFor":"雙棍在身體兩側。","alignmentCues":["每個輪都在髖部外側。","速度一致。"],"props":["兩根短棍"],"commonMistakes":["輪面向內傾斜。","雙手漸漸分開。"]},"double-staff-split-wheels":{"name":"雙短杖分輪","description":"兩側各轉一個輪，相差四分之一圈，像走路的雙腿。","goodFor":"身體兩側，分時轉動。","alignmentCues":["一根朝上，一根持平。","保持穩定的錯位。"],"props":["兩根短杖"],"commonMistakes":["同步起來了。","歪了。"]},"double-staff-windmill":{"name":"雙棍風車","description":"兩側的輪子朝相反方向轉，就像從側面看的風車。","goodFor":"兩手方向相反。","alignmentCues":["一正一反。","速度均勻。"],"props":["兩根短棍"],"commonMistakes":["兩棍偏向同一側。","速度不均。"]},"double-staff-reverse":{"name":"雙棍反轉","description":"兩棍在身前反轉，錯開半拍。","goodFor":"兩根棍，兩個方向。","alignmentCues":["穩住錯位。","兩棍同一平面。"],"props":["兩根短棍"],"commonMistakes":["兩棍相撞。","錯位丟了。"]},"double-staff-helicopters":{"name":"雙棍直升機","description":"每側肩上各一個直升機，兩邊同步轉。","goodFor":"雙棍舉過頭頂。","alignmentCues":["兩棍保持水平。","手臂放鬆。"],"props":["兩根短棍"],"commonMistakes":["兩棍相碰。","手臂累了往下掉。"]},"double-staff-isolations":{"name":"雙棍定點","description":"兩手同時各做一個定點，兩個中心並排保持不動。","goodFor":"同時兩個定點。","alignmentCues":["兩個固定點。","雙手一起畫圓。"],"props":["兩根短棍"],"commonMistakes":["中心點跑了。","一隻手跟不上。"]},"hoop-waist":{"name":"腰部呼啦圈","description":"站立時一隻腳稍微在前。將呼啦圈抵住下背部，把它繞腰部丟擲，每次呼啦圈經過身前時，讓腹部前後發力（不是畫圓）。","goodFor":"第一個呼啦圈技能；建立核心節奏。","modifications":["使用更大、更重的呼啦圈：它會轉得更慢。"],"alignmentCues":["前後擺動，不要繞圈。","當呼啦圈經過腹部時推動它。"],"props":["呼啦圈"],"commonMistakes":["像草裙舞者一樣繞髖。","太小或太輕的呼啦圈。"]},"hoop-hand-spin":{"name":"手轉","description":"將呼啦圈拿在身前，手放在圈內，拇指朝上。把它推入繞手虎口旋轉的狀態，讓呼啦圈在身前保持平直。","goodFor":"離體呼啦圈基礎。","props":["呼啦圈"]},"hoop-chest":{"name":"胸部呼啦圈","description":"將手臂舉過頭頂，在胸部周圍轉呼啦圈，讓胸腔前後擺動，同時保持髖部穩定。","goodFor":"隔離胸腔並建立上半身控制。","props":["呼啦圈"]},"hoop-lasso":{"name":"套索","description":"將呼啦圈舉過頭頂，像套索一樣在頭頂上方水平畫圓，讓呼啦圈繞著手旋轉。","goodFor":"頭頂水平面的控制。","props":["呼啦圈"]},"hoop-wedgie":{"name":"夾褲","description":"讓呼啦圈在牆面平面旋轉，並用拇指和手指之間的虎口接住它，讓它在那裡滾動和擺動，然後再繼續旋轉。","goodFor":"握持控制和流暢的過渡停留。","props":["呼啦圈"]},"hoop-knees":{"name":"膝部呼啦圈","description":"雙腳併攏，透過膝蓋前後發力，讓呼啦圈持續繞膝蓋旋轉。","goodFor":"下半身呼啦圈和電梯練習。","props":["呼啦圈"]},"hoop-pass":{"name":"手對手傳遞","description":"在身前轉動呼啦圈，每轉一圈就把它從一隻手傳到另一隻手，保持平面穩定。","goodFor":"連線兩側的離身技巧。","props":["呼啦圈"]},"hoop-isolation":{"name":"呼啦圈隔離","description":"讓手繞著呼啦圈移動，使圈心固定在身前的空中，呼啦圈圍繞那個點轉動。","goodFor":"經典的呼啦圈錯覺。","props":["呼啦圈"]},"hoop-escalator":{"name":"電梯","description":"保持呼啦圈轉動，同時讓它從腰部走到膝蓋，再回到胸部，每小節移動一個身體區域。","goodFor":"把每個身體呼啦圈區域連成一段流動。","props":["呼啦圈"]},"hoop-neck":{"name":"頸部呼啦圈","description":"微微傾斜頭部，讓輕巧的呼啦圈繞頸部轉動，用頭和肩膀的小幅律動引導。","goodFor":"一個表演動作，訓練小而精準的律動。","avoidIf":["頸部疼痛。"],"props":["呼啦圈"]},"hoop-reverse-waist":{"name":"反向腰上轉圈","description":"腰上的圈反過來轉。換一隻腳在前，把圈往新方向甩出去，保持同樣的前後推送節奏。","goodFor":"兩個方向都練平衡，之後每個招式朝哪邊都能做。","alignmentCues":["換前腳。","同樣的推送，新的方向。"],"props":["呼啦圈"],"commonMistakes":["繞著胯部轉圈。","太早放棄弱側。"]},"hoop-hips":{"name":"胯部轉圈","description":"讓圈從腰部下沉到髖骨，用骨盆更低、更小的律動把它穩在那裡。","goodFor":"掌控腰部以下，向膝蓋邁進一步。","alignmentCues":["膝蓋放鬆。","律動來自骨盆，不是肚子。"],"props":["呼啦圈"],"commonMistakes":["讓它順勢滑下來。","律動太大。"]},"hoop-thighs":{"name":"大腿轉圈","description":"雙腳併攏，用快速小幅的膝蓋彈動，讓圈在大腿上部持續轉動。","goodFor":"腿部節奏，以及胯與膝的聯動。","alignmentCues":["雙腳併攏。","快速小幅彈動。"],"props":["呼啦圈"],"commonMistakes":["雙腳分開。","彈動太慢。"]},"hoop-reverse-chest":{"name":"反向胸部轉圈","description":"反方向做胸部轉圈，雙臂抬起，用肋骨驅動圈。","goodFor":"身體上部，兩個方向都能轉。","alignmentCues":["手臂舉高，別擋路。","胸廓前後擺動。"],"props":["呼啦圈"],"commonMistakes":["手臂垂進圈裡。","胯部代勞。"]},"hoop-shoulder":{"name":"肩膀轉圈","description":"雙臂舉過頭頂，讓圈繞著肩膀和上胸轉動。","goodFor":"上身轉圈。","alignmentCues":["雙臂筆直上舉。","肩膀小幅律動。"],"props":["呼啦圈"],"commonMistakes":["手臂向內彎。","圈滑落到胸前。"]},"hoop-arm":{"name":"手臂轉圈","description":"一隻手臂伸直舉過頭頂，讓圈繞前臂旋轉，手畫小圈保持轉動。","goodFor":"肢體轉圈，加上舉臂套索的感覺。","alignmentCues":["手臂伸直，手舉過頭頂。","手畫小圈。"],"props":["圈"],"commonMistakes":["整條手臂畫圈。","手臂向前漂移。"]},"hoop-elbow":{"name":"手肘轉圈","description":"手臂向體側伸出、屈肘，圈繞肘關節轉動。","goodFor":"遠離身體的肢體控制。","alignmentCues":["大臂保持水平。","肘部畫小圈。"],"props":["呼啦圈"],"commonMistakes":["肘部下垂。","圈滑向肩膀。"]},"hoop-foot":{"name":"腿部轉圈","description":"抬起一條腿，讓圈繞小腿旋轉，腳畫小圈保持轉動。","goodFor":"平衡與腿部控制。","alignmentCues":["支撐腿保持有力。","腳畫小圈。"],"props":["呼啦圈"],"commonMistakes":["失去平衡。","畫圈幅度太大。"]},"hoop-full-escalator":{"name":"完整電梯","description":"讓圈從膝蓋一路爬升到肩膀，再不停頓地滑落回來。","goodFor":"一個連貫動作貫穿全身。","alignmentCues":["攀升時加快律動。","手臂隨圈上升。"],"props":["呼啦圈"],"commonMistakes":["腰部跳到胸口時掉圈。","手臂擋路。"]},"hoop-vortex":{"name":"漩渦","description":"在頭頂把圈甩成套索，讓它繞著肩膀和胸口螺旋落下，在腰部接住。","goodFor":"把離體轉圈和貼身轉圈連起來。","alignmentCues":["放開時保持套索的速度。","在圈落下之前就開始律動。"],"props":["呼啦圈"],"commonMistakes":["鬆手太慢。","圈在下落時傾斜。"]},"hoop-duck-out":{"name":"鑽圈","description":"讓圈從腰部一路上行越過胸口，在頭頂抓住轉入套索，再帶下來在身前做手轉。","goodFor":"利落地把圈帶離身體。","alignmentCues":["用肋部帶動上提。","踩著節拍在頭頂抓圈。"],"props":["呼啦圈"],"commonMistakes":["抓得太早。","轉速下降。"]},"hoop-drop-in":{"name":"落圈","description":"從頭頂套索開始，鬆手讓圈落在胸口接住，再讓它落到腰部。","goodFor":"從離身回到身上的最簡單方式。","alignmentCues":["圈下落時手臂上抬。","帶著起伏接住。"],"props":["圈"],"commonMistakes":["落得太快。","手臂下壓夾緊。"]},"hoop-chest-lift":{"name":"胸前提圈","description":"用更有力的起伏，把圈從腰部提到胸前，再落回腰部。","goodFor":"在身體各部位之間轉換。","alignmentCues":["加快起伏讓它上升。","手臂抬得太早。"],"props":["圈"],"commonMistakes":["換位時圈失控。","手臂下垂。"]},"hoop-knee-drop":{"name":"落膝","description":"讓圈從腰部沉到膝蓋，在膝上保持旋轉，再彈回腰部。","goodFor":"下半身換位。","alignmentCues":["落膝時雙腳併攏。","加大彈動讓它回升。"],"props":["圈"],"commonMistakes":["雙腳分開。","回升時圈失控。"]},"hoop-side-spin":{"name":"側旋","description":"在身側的輪平面上用手旋轉，圈像車輪一樣在身邊轉動。","goodFor":"圈的輪平面。","alignmentCues":["圈豎直立在身側。","手與髖同高。"],"props":["圈"],"commonMistakes":["圈打到腿了。","平面傾斜了。"]},"hoop-reverse-hand-spin":{"name":"反向手轉","description":"在身前朝反方向轉動的手轉。","goodFor":"離體雙向。","alignmentCues":["同一平面，反方向。","拇指保持朝上。"],"props":["圈"],"commonMistakes":["晃動了。","速度變慢了。"]},"hoop-reverse-lasso":{"name":"反向套索","description":"頭頂套索朝反方向轉動。","goodFor":"雙向套索。","alignmentCues":["圈保持水平。","手部小繞圈。"],"props":["圈"],"commonMistakes":["傾斜了。","手臂大繞環。"]},"hoop-palm-spin":{"name":"頭頂掌心轉","description":"把手轉舉過頭頂，託在攤開的手掌上，圈面朝前在頭頂轉動。","goodFor":"把離體旋轉伸向高處。","alignmentCues":["手臂伸直。","手掌攤開。"],"props":["圈"],"commonMistakes":["圈往後漂了。","手臂彎曲了。"]},"hoop-coin-flip":{"name":"硬幣翻轉","description":"把圈豎直平衡在指尖上，輕輕一彈，讓它像拋起的硬幣一樣繞豎直的中軸旋轉。","goodFor":"精細的手指控制和全新的旋轉軸。","alignmentCues":["圈保持豎直。","先輕彈，再讓它自己轉。"],"props":["圈"],"commonMistakes":["圈在傾倒。","握得太緊。"]},"hoop-cateye":{"name":"貓眼","description":"握住圈緣的一側，繞豎直中軸來回擺動，從正面看圈面像貓眼一樣變窄又變寬。","goodFor":"擺動動作加搶眼的視覺錯覺。","alignmentCues":["手穩穩停在圈緣。","均勻擺動。"],"props":["呼啦圈"],"commonMistakes":["手在移動。","擺動不均勻。"]},"hoop-weave":{"name":"編織","description":"手轉的圈從身體一側滑向另一側，圈面隨胸口轉動。","goodFor":"把旋轉帶過身體。","alignmentCues":["胸口跟著轉。","讓它一直轉。"],"props":["呼啦圈"],"commonMistakes":["中途停住。","圈面傾斜。"]},"hoop-halo":{"name":"光環","description":"圈在頭頂上方水平繞轉，舉起的手貼著圈沿，隨圈繞行。","goodFor":"在頭頂高度繞圈。","alignmentCues":["圈繞頭時保持水平。","手貼近頭部。"],"props":["呼啦圈"],"commonMistakes":["圈在身前下垂。","低頭。"]},"hoop-toss":{"name":"拋圈","description":"把旋轉中的圈垂直向上拋起，再接住讓它繼續旋轉。","goodFor":"丟擲並接住旋轉中的圈。","alignmentCues":["垂直向上拋。","在丟擲的位置接住。"],"props":["呼啦圈"],"commonMistakes":["拋向前方。","抓圈沿太晚。"]},"hoop-boomerang":{"name":"迴旋圈","description":"帶上回旋把圈向前下方丟擲，讓它沿地面滾出去，再滾回你身邊。","goodFor":"練習迴旋，一個有趣的地面花式。","alignmentCues":["手腕往回一抖。","低一點，向前拋。"],"props":["呼啦圈"],"commonMistakes":["迴旋不夠。","拋得太高。"]},"hoop-jump-through":{"name":"跳圈","description":"像握跳繩一樣雙手握圈：把圈掄過頭頂，圈經過腳下時跳過去。","goodFor":"節奏感、協調性，外加一陣心肺鍛鍊。","alignmentCues":["小跳一下，膝蓋放鬆。","用手腕發力揮圈。"],"props":["呼啦圈"],"commonMistakes":["起跳太早了。","手臂擺幅太大。"]},"hoop-behind-back-pass":{"name":"背後傳圈","description":"手轉的圈在背後從一隻手傳到另一隻手，再從身前繞回來。","goodFor":"讓圈繞身體完整傳一圈。","alignmentCues":["讓它在背後繼續轉。","接圈的手向後伸。"],"props":["呼啦圈"],"commonMistakes":["圈在背後停轉了。","圈打到背了。"]},"hoop-under-leg-pass":{"name":"胯下傳圈","description":"手對手的傳圈，從抬起的右腿下方穿過。","goodFor":"在傳圈中加入腿部動作。","alignmentCues":["將膝蓋抬高至呼啦圈處。","在髖部摺疊，背部伸展，坐入站立的膝蓋。","當呼啦圈從另一側出來時，再次站起。"],"props":["呼啦圈"],"commonMistakes":["背部彎曲以夠到道具，而不是在髖部摺疊。","膝蓋位置過低，導致呼啦圈碰到大腿。","疾馳。"]},"hoop-corkscrew":{"name":"開瓶器","description":"套索螺旋下降到胯部再回升，圈畫出開瓶器般的軌跡。","goodFor":"讓套索在不同高度間移動。","alignmentCues":["屈膝下沉。","讓圈保持水平。"],"props":["呼啦圈"],"commonMistakes":["圈在低位時傾斜了。","旋轉變慢了。"]},"hoop-barrel-roll":{"name":"桶滾","description":"手轉的圈每四拍繞身體一整圈，讓圈繞著你滾動。","goodFor":"繞身體一整圈的離體流動。","alignmentCues":["跟著圈轉身。","全程保持旋轉。"],"props":["呼啦圈"],"commonMistakes":["圈勾到身體了。","旋轉在背後停住了。"]},"hoop-chest-roll":{"name":"胸滾","description":"把手轉的圈放到胸口，讓它滾向另一隻手。","goodFor":"第一個圈滾動動作。","alignmentCues":["挺起胸。","滾動時雙臂張開。"],"props":["呼啦圈"],"commonMistakes":["胸口塌陷。","抓得太早。"]},"hoop-back-roll":{"name":"背滾","description":"呼啦圈沿肩背從一隻手滾向另一隻手。","goodFor":"在身體後方滾動。","alignmentCues":["肩胛骨向中間夾緊。","頭稍微前傾。"],"props":["呼啦圈"],"commonMistakes":["弓背。","呼啦圈掉落。"]},"hoop-isopop":{"name":"定軸彈圈","description":"一種定軸動作：每兩拍把圈向側面頓停並彈出，然後繼續。","goodFor":"定軸中的重音與頓停。","alignmentCues":["卡著節拍彈出。","兩次彈出之間，定軸保持乾淨。"],"props":["呼啦圈"],"commonMistakes":["彈出幅度太大。","圓心亂晃。"]},"hoop-wheel-isolation":{"name":"側面定軸","description":"在身體一側的輪平面內做定軸。","goodFor":"第二個平面中的定軸。","alignmentCues":["圓心固定在身側。","手繞著圓心畫圓。"],"props":["呼啦圈"],"commonMistakes":["圓心漂移。","圈面傾斜。"]},"hoop-floor-isolation":{"name":"水平定軸","description":"圈水平放置、圓心固定、手繞圈畫圓的定軸。","goodFor":"地面平面中的定軸。","alignmentCues":["圈保持水平。","圓心固定。"],"props":["呼啦圈"],"commonMistakes":["圈面傾斜。","圓心漂移。"]},"doubles-hand-spins":{"name":"雙圈手轉","description":"雙手各持一圈，在身前呈映象旋轉。","goodFor":"雙圈入門動作。","alignmentCues":["兩圈並排。","兩手速度一致。"],"props":["雙圈"],"commonMistakes":["雙圈相撞。","其中一圈變慢。"]},"doubles-offset-spins":{"name":"雙圈錯位旋轉","description":"雙手同向旋轉雙圈，錯開半圈。","goodFor":"雙手節奏各自獨立。","alignmentCues":["一手在上，另一手在下。","同方向。"],"props":["雙圈"],"commonMistakes":["正在同步。","相撞。"]},"doubles-side-spins":{"name":"雙圈側旋","description":"每側髖旁各有一圈在輪面內旋轉。","goodFor":"輪面內的雙圈動作。","alignmentCues":["雙圈豎直。","避開雙腿。"],"props":["雙圈"],"commonMistakes":["碰到腿了。","圈面傾斜。"]},"doubles-floor-spins":{"name":"雙圈套索","description":"雙手頭頂各一個套索，呈映象。","goodFor":"頭頂雙圈。","alignmentCues":["雙圈保持水平。","手部畫小圈。"],"props":["雙圈"],"commonMistakes":["雙圈相觸。","手臂發酸。"]},"doubles-wedgies":{"name":"雙圈 Wedgie","description":"每手各一個 wedgie，雙圈在虎口處搖擺。","goodFor":"雙圈搖擺動作。","alignmentCues":["拇指向外。","搖擺均勻。"],"props":["雙圈"],"commonMistakes":["雙圈相撞。","節奏不均。"]},"doubles-coin-flips":{"name":"雙圈硬幣翻轉","description":"雙手同時各做一次硬幣翻轉。","goodFor":"雙圈手指控制。","alignmentCues":["兩圈都豎直。","同時輕彈。"],"props":["雙圈"],"commonMistakes":["圈歪了。","圈相撞了。"]},"doubles-isolations":{"name":"雙圈定點","description":"雙手各轉一個定點，兩個圓心並排固定。","goodFor":"同時兩個定點。","alignmentCues":["兩個靜止的圓心。","雙手一起畫圈。"],"props":["雙圈"],"commonMistakes":["圓心跑偏了。","雙圈相撞。"]},"doubles-toss":{"name":"雙圈拋接","description":"把兩個旋轉的圈一起拋向空中，接住後回到雙圈旋轉。","goodFor":"雙圈脫手。","alignmentCues":["一起垂直向上拋。","哪裡拋的哪裡接。"],"props":["雙圈"],"commonMistakes":["拋得不齊。","往前偏了。"]},"doubles-waist-and-hand":{"name":"腰圈加手轉","description":"腰上保持一個圈旋轉，同時左手再轉第二個圈。","goodFor":"注意力分散在身體和手之間。","alignmentCues":["胯部保持律動。","手上的圈在身體圈前方。"],"props":["雙圈"],"commonMistakes":["身體圈慢下來了。","手上的圈撞到身體圈。"]},"doubles-chest-and-hand":{"name":"胸圈加手轉","description":"一隻手臂抬起做胸口轉圈，另一隻手同時轉第二個圈。","goodFor":"高位身體轉圈配合手上花式。","alignmentCues":["一隻手臂舉高。","肋部發力帶動身體圈。"],"props":["雙圈"],"commonMistakes":["手臂垂下來擋到胸圈。","律動丟了。"]},"doubles-waist-and-lasso":{"name":"腰圈加套索","description":"腰上轉圈，頭頂套索：兩個圈同時在兩個高度。","goodFor":"兩個高度同時轉圈。","alignmentCues":["胯部律動，手部畫圈。","套索保持在頭頂高度。"],"props":["雙圈"],"commonMistakes":["身體圈下落。","套索傾斜。"]},"poi-one-hand-spin":{"name":"單poi正旋","description":"一隻poi像時鐘指標一樣在身前畫圈，poi頭從身側輕輕掃過。手腕畫著小而穩的圈，繩始終保持繃緊。","goodFor":"感受繩的拉力，以及每拍一圈的節奏。","alignmentCues":["手腕畫小圈，poi畫大圈。","讓圓圈在身前保持平整，像一塊窗玻璃。"],"props":["單poi"],"commonMistakes":["用肩膀揮動。","讓圓圈向你傾斜。"]},"poi-wall-spin":{"name":"正向牆面旋轉","description":"兩隻poi在你面前同時向前轉動，一邊一隻位於肩膀旁，並排如同一根軸上的兩個輪子。這是雙poi的第一個動作。","goodFor":"兩隻poi彼此同步，並與節拍一致。","alignmentCues":["兩個球頭同時到達最高點。","雙手間距約與肩同寬。"],"props":["一對poi"],"commonMistakes":["一隻poi落後於另一隻。","圓圈漸漸漂到一起。"]},"poi-reverse-wall-spin":{"name":"反向牆面旋轉","description":"把牆面旋轉反過來：球頭沿外側上升，從中間落下。","goodFor":"編織和花朵之前，先把兩個方向都練熟。","alignmentCues":["平面保持不變，只是方向相反。","用手腕背面帶動畫圓。"],"props":["一對 poi"],"commonMistakes":["不小心滑回正向旋轉。","平面向前傾斜。"]},"poi-split-time":{"name":"分拍牆面旋轉","description":"兩個 poi 朝同一方向轉動，但相差半圈：一個在頂點時，另一個在底點。所有編織都建立在這個節奏上。","goodFor":"雙手節奏各自獨立。","alignmentCues":["上、下、上、下：兩個球頭交替出現。","在正拍和半拍上，數出每個 poi 的頂點。"],"props":["一對 poi"],"commonMistakes":["不知不覺又回到同拍。","雙手速度不一致。"]},"poi-butterfly":{"name":"蝴蝶","description":"雙手在身前併攏，兩個 poi 朝相反方向轉動，在頂點和底點相遇，就像蝴蝶的翅膀。","goodFor":"反向節奏，雙手併攏。","alignmentCues":["球頭在頂點和底點輕輕相觸。","手腕幾乎相碰。"],"props":["一對 poi"],"commonMistakes":["平面交叉時球頭相撞。","雙手漸漸分開。"]},"poi-reverse-butterfly":{"name":"反向蝴蝶","description":"把蝴蝶的兩隻翅膀反過來轉：球頭一起從中間上升，再沿兩側落下。","goodFor":"正反兩個方向都練蝴蝶，保持均衡。","alignmentCues":["到達頂點時，在中間相會。","和正向蝴蝶一樣，雙手保持併攏。"],"props":["一對 poi"],"commonMistakes":["球頭在頂部纏在一起。","一側翅膀下垂。"]},"poi-chase-the-sun":{"name":"追日","description":"雙手在身前併攏，分拍節奏：兩個球頭相互追隨，沿著同一個大圓轉動，始終相差半圈。","goodFor":"雙手併攏的分拍練習，為編織做好準備。","alignmentCues":["一個球頭始終在另一個的正對面。","雙手如一體般移動。"],"props":["一對 poi"],"commonMistakes":["球頭互相追上，半圈差距消失。","雙手分開。"]},"poi-wheels":{"name":"正向車輪","description":"雙 poi 在身側轉動，像腳踏車的車輪，頂端向前滾動。","goodFor":"車輪平面，位於身體兩側。","alignmentCues":["圓圈與身體兩側平行。","手肘放鬆，貼近身體。"],"props":["一對 poi"],"commonMistakes":["poi 掃到腿。","車輪向外撇。"]},"poi-reverse-wheels":{"name":"反向車輪","description":"車輪在身側向後滾動，球頭在前方升起、在身後落下。","goodFor":"車輪平面內的兩個方向。","alignmentCues":["同樣的車輪，方向反轉。","雙肩下沉放鬆。"],"props":["一對 poi"],"commonMistakes":["車輪漂到身體後方。","手腕發僵。"]},"poi-fountain":{"name":"噴泉","description":"分拍車輪：一個 poi 上升時另一個下降，就像身側噴泉中的水。","goodFor":"車輪平面內的分拍，行走編織的基礎。","alignmentCues":["一上一下。","雙手節奏保持均勻。"],"props":["一對 poi"],"commonMistakes":["節奏塌成同拍。","車輪向內傾斜。"]},"poi-opposite-wheels":{"name":"對向車輪","description":"一個輪向前轉，另一個向後轉，球頭在頂部和底部交錯而過。","goodFor":"雙手反向轉動的協調。","alignmentCues":["雙手同時到達頂端。","每隻手保持自己的方向。"],"props":["一對 poi"],"commonMistakes":["雙手變成同一方向。","一個輪越轉越小。"]},"poi-overhead":{"name":"頭頂水平旋轉","description":"雙 poi 在頭頂水平畫圓，像直升機螺旋槳，轉動時外側略微下垂。","goodFor":"水平面，以及頭頂上方穩定的雙肩。","alignmentCues":["雙手略高於頭頂。","讓 poi 自然放平，別用蠻力。"],"props":["一對 poi"],"commonMistakes":["聳肩。","poi 在身前下垂。"]},"poi-low-floor":{"name":"髖部高度地面旋轉","description":"把地平面降到髖部：POI 在身側腰部高度繞圈掃動。","goodFor":"地面與牆面混合招式中用到的低位地平面。","alignmentCues":["雙手張開置於髖部兩側。","讓圓圈保持水平。"],"props":["一對 POI"],"commonMistakes":["POI 打到大腿。","身體前傾。"]},"poi-three-beat-weave":{"name":"三拍編織","description":"標誌性的 POI 動作：分時的 POI 從身體一側擺向另一側，隨著平面換邊，雙臂交叉又展開。","goodFor":"每位 POI 玩家都由此起步的流動動作。","alignmentCues":["肩膀跟著編織轉。","平面略微向兩側傾斜。"],"props":["一對 POI"],"commonMistakes":["雙手保持在中間。","交叉時 POI 相互碰撞。"]},"poi-reverse-three-beat-weave":{"name":"反向三拍編織","description":"兩個 POI 都反向旋轉的三拍編織。雙臂從上方交叉，而不是從下方。","goodFor":"雙向編織。","alignmentCues":["同樣的左右軌跡，反向旋轉。","雙手保持在胸口高度。"],"props":["一對 POI"],"commonMistakes":["POI 頭在頂端相撞。","編織範圍縮向一側。"]},"poi-two-beat-weave":{"name":"兩拍編織","description":"更快的編織，每一拍換一次邊。更快的交叉讓動作更密集、更緊湊。","goodFor":"快速換邊。","alignmentCues":["幅度更小、更快的轉肩。","手腕在靠近胸前的位置交叉。"],"props":["一對 POI"],"commonMistakes":["又退回三拍節奏。","分時丟失。"]},"poi-five-beat-weave":{"name":"五拍編織","description":"更長、更寬的編織：POI 在每一側多轉幾圈才交叉回來。","goodFor":"在更長的樂句中保持編織的形狀。","alignmentCues":["大幅度的轉肩。","交叉保持流暢。"],"props":["一對 POI"],"commonMistakes":["交叉太早。","平面逐漸攤平。"]},"poi-behind-back-weave":{"name":"背後編織","description":"每隔一組拍子，右手的 poi 就繞到背後再回到身前，節奏絲毫不亂。","goodFor":"讓簡單圖案煥然一新的繞身技巧。","alignmentCues":["手往臀部後下方伸。","目視前方，相信節奏。"],"props":["一對 poi"],"commonMistakes":["Poi 打到後背。","前面的 poi 停住，後面的還在轉。"]},"poi-crossers":{"name":"交叉手","description":"同拍立面旋轉，手臂在身前交叉再開啟，兩個 poi 每拍互換左右。","goodFor":"跟著拍子交叉手臂。","alignmentCues":["在手腕處交叉。","讓兩個 poi 步調一致。"],"props":["一對 poi"],"commonMistakes":["交叉時繩索纏在一起。","其中一個 poi 卡住。"]},"poi-reels":{"name":"輪轉","description":"兩個 poi 在身體同一側一起轉滿一小節，再一起盪到另一側。","goodFor":"把兩個 poi 當成一個整體繞身移動。","alignmentCues":["雙手保持靠攏。","轉動身體，面向每一側。"],"props":["一對 poi"],"commonMistakes":["交叉時雙手分開。","交叉沒踩在拍子上。"]},"poi-thread-the-needle":{"name":"穿針引線","description":"兩個 poi 反向分拍旋轉，手臂交叉：一個 poi 從另一個剛讓出的空隙中穿過。","goodFor":"雙手時機精準配合。","alignmentCues":["空隙一開就交叉。","圓圈收緊。"],"props":["一對 poi"],"commonMistakes":["交叉到一半，兩個 poi 相撞。","分拍不知不覺滑成同拍。"]},"poi-buzzsaw":{"name":"電鋸","description":"雙手併攏相貼，兩個 poi 合為一體旋轉，繩索並排，宛如一片旋轉的鋸片。","goodFor":"讓兩個 poi 完全同步。","alignmentCues":["雙掌相貼，手腕放鬆。","一個圓，兩顆球。"],"props":["一對 poi"],"commonMistakes":["兩顆球分開了。","雙手漸漸分開。"]},"poi-one-hand-isolation":{"name":"單Poi定點","description":"手在頭的正對面以同樣的速度畫圈，繩的中段彷彿被釘在空中，Poi繞著它轉動。","goodFor":"第一個幻象：空中一個不動的點。","alignmentCues":["手始終與頭相對。","看繩的中段，別盯著頭。"],"props":["單Poi"],"commonMistakes":["手畫圈太小，定點會飄走。","在頂端加速了。"]},"poi-isolation":{"name":"定點","description":"雙手同時做定點，兩個靜止點並排懸在你面前。","goodFor":"雙手控制幻象。","alignmentCues":["雙手各與自己的頭相對。","手肘放鬆，肩膀下沉。"],"props":["雙Poi"],"commonMistakes":["一隻手丟了定點。","定點向前漂移。"]},"poi-split-isolation":{"name":"分時定點","description":"兩個定點相差半圈：一手在上，一手在下，靜止點穩穩不動。","goodFor":"分時節奏下的定點時機。","alignmentCues":["雙手上下交替。","兩個定點保持齊平。"],"props":["雙Poi"],"commonMistakes":["雙手趨於同步。","定點下沉。"]},"poi-wheel-isolation":{"name":"輪平面定點","description":"在身側的輪平面做定點，靜止點懸停在兩旁。","goodFor":"在第二個平面做定點。","alignmentCues":["定點與髖部齊平。","雙手沿身體兩側平行畫圈。"],"props":["雙Poi"],"commonMistakes":["平面向外扭轉。","雙手離身體太近。"]},"poi-extension":{"name":"延伸","description":"手臂與繩連成一條直線，手大幅畫圈，讓Poi畫出最大的圓。","goodFor":"大開大合的圖形，以及貓眼的延伸半段。","alignmentCues":["從肩膀向外伸展。","手與頭和圓心三點一線。"],"props":["雙Poi"],"commonMistakes":["手腕彎了。","圓在底部塌陷。"]},"poi-cateye":{"name":"貓眼","description":"一隻手做隔離，另一隻手做延展。兩條軌跡重疊成杏仁形，就像貓的眼睛。","goodFor":"同時混合兩種不同的手部軌跡。","alignmentCues":["隔離的手畫小圈，延展的手畫大圈。","雙手同時從頂端開始。"],"props":["一對 poi"],"commonMistakes":["雙手做同樣的動作。","形狀歪斜。"]},"poi-one-hand-antispin":{"name":"單 poi 反旋","description":"手往一個方向畫圈，poi 卻朝反方向旋轉，手每繞一圈，poi 就轉三圈，畫出四瓣花。","goodFor":"雙 poi 花式之前，先找反旋的感覺。","alignmentCues":["手圈畫大、放慢。","每個花瓣尖都落在手圈邊緣。"],"props":["單 poi"],"commonMistakes":["poi 翻回普通正旋。","花瓣不均勻。"]},"poi-antispin-flower":{"name":"四瓣反旋","description":"雙手同時做反旋花，兩朵四瓣花並排綻放。","goodFor":"經典的 poi 花朵。","alignmentCues":["雙手一起畫圈。","花瓣對齊：上、側、下、側。"],"props":["一對 poi"],"commonMistakes":["一隻手掉回正旋。","花朵向前漂移。"]},"poi-split-antispin":{"name":"分時反旋","description":"四瓣花，兩個 poi 相差半圈，一朵花的花瓣正好填滿另一朵的空隙。","goodFor":"用分時節奏開花。","alignmentCues":["雙手在各自的圓圈上正好相對。","花瓣交錯。"],"props":["一對 poi"],"commonMistakes":["分時塌掉，變成同時。","雙手畫圈的速度不一樣。"]},"poi-three-petal-antispin":{"name":"三瓣反旋","description":"三瓣花：手每繞一圈，poi 反旋兩圈，開出三角形的花朵。","goodFor":"靠改變手速來改變花瓣數量。","alignmentCues":["手速要比四瓣花時更快。","花瓣均勻分佈在三個點上。"],"props":["一對 poi"],"commonMistakes":["不小心滑回四瓣。","手圈越畫越小。"]},"poi-five-petal-antispin":{"name":"五瓣反旋","description":"手每畫一圈，poi 反轉四次，構成一朵五瓣花，手要更慢、幅度更大。","goodFor":"精細控制手與 poi 的速度比。","alignmentCues":["手要非常慢。","手每畫一圈，數 poi 轉四圈。"],"props":["一對 poi"],"commonMistakes":["花瓣數亂了。","手停了下來。"]},"poi-wheel-antispin":{"name":"輪面反旋","description":"在身體兩側的輪面上畫四瓣反旋花。","goodFor":"在輪面畫花。","alignmentCues":["花面與身體兩側平行。","雙手在髖部旁邊畫圈。"],"props":["一對 poi"],"commonMistakes":["平面朝內傾斜。","花瓣擦到腿。"]},"poi-overhead-antispin":{"name":"頭頂反旋","description":"反旋花平鋪在頭頂上方，花瓣朝你頭頂四周展開。","goodFor":"在水平面畫花。","alignmentCues":["雙手在頭頂正上方。","花瓣保持水平。"],"props":["一對 poi"],"commonMistakes":["花面向前傾斜。","肩膀疲勞下垂。"]},"poi-antispin-and-spin":{"name":"反旋與正旋","description":"右手畫四瓣反旋花，左手保持普通正旋。","goodFor":"雙手獨立性：同時做出兩種不同的形狀。","alignmentCues":["正旋的手保持緊湊。","畫花的手繞大圈。"],"props":["一對 poi"],"commonMistakes":["雙手互相模仿。","正旋的 poi 越轉越慢。"]},"poi-inspin-flower":{"name":"四瓣順旋","description":"手與 poi 同方向緩慢畫圈，手每繞一圈，poi 轉五圈，畫出指向內側的花瓣環。","goodFor":"順旋花，反旋的對應招式。","alignmentCues":["手和 poi 朝同一方向轉動。","花瓣環朝向中心。"],"props":["一對 poi"],"commonMistakes":["手圈轉得太快。","花瓣環不均勻。"]},"poi-three-petal-inspin":{"name":"三瓣正轉","description":"正轉：手每繞一圈，poi轉四圈，畫出三環的花朵。","goodFor":"改變正轉的花瓣數量。","alignmentCues":["手速比四瓣時稍快。","三個環，間距均勻。"],"props":["雙poi"],"commonMistakes":["數錯節拍。","環變扁。"]},"poi-wall-wheel-hybrid":{"name":"牆面–輪面混合","description":"每轉一圈，poi就在正面與側面之間切換平面，並在poi頭豎直朝下時轉向。","goodFor":"切換平面而不打斷旋轉。","alignmentCues":["在poi指向地面時切換。","轉動手腕，而不是整條手臂。"],"props":["雙poi"],"commonMistakes":["在繞圈中途切換。","poi在平面之間晃動。"]},"poi-wheel-floor-hybrid":{"name":"輪面–地面混合","description":"poi在身側旋轉與水平掃動之間交替，並在指向前方時切換。","goodFor":"第二種包含水平面的混合。","alignmentCues":["在poi指向前方時切換。","雙手保持髖部高度。"],"props":["雙poi"],"commonMistakes":["切換時poi下沉。","跟不上節拍。"]},"poi-floor-wall-hybrid":{"name":"地面–牆面混合","description":"從頭頂的水平面轉到身前的牆面，再轉回去，在poi指向兩側時切換。","goodFor":"連線頭頂平面與牆面。","alignmentCues":["在poi指向兩側時切換。","雙手平穩地抬起和放下。"],"props":["雙poi"],"commonMistakes":["poi打到頭部。","切換不均勻。"]},"poi-top-stall":{"name":"停頓","description":"poi升到頂點，在手的正上方停頓一瞬，然後沿原路落回。","goodFor":"停住並反轉：這是停頓組合與hyperloop的基礎。","alignmentCues":["在poi到達頂點時抬手。","讓它懸住，再引導它回落。"],"props":["單poi"],"commonMistakes":["繩索變鬆並纏繞。","停頓太倉促。"]},"poi-stalls":{"name":"雙急停","description":"兩隻Poi並排同時在最高點急停，然後反轉。","goodFor":"雙手急停控制。","alignmentCues":["兩隻Poi同時到達最高點。","雙手同時抬起。"],"props":["一對Poi"],"commonMistakes":["一隻Poi急停偏晚。","Poi在下落時相撞。"]},"poi-side-stall":{"name":"側向急停","description":"Poi不在頂部，而是在身體兩側急停，各自停在齊肩高度後再擺回。","goodFor":"在圓的不同位置急停。","alignmentCues":["在Poi指向側面時停住。","手臂放鬆。"],"props":["一對Poi"],"commonMistakes":["Poi往下掉而不是停住。","節奏逐漸偏移。"]},"poi-chasing-stalls":{"name":"追逐急停","description":"急停相差半拍：一隻Poi在最高點停住時，另一隻還在上升途中。","goodFor":"分拍急停。","alignmentCues":["先停一隻，再停另一隻。","雙手保持在胸口高度。"],"props":["一對Poi"],"commonMistakes":["兩隻Poi同時急停。","第二下急停太急。"]},"poi-hyperloop":{"name":"超級迴路列車系統","description":"一種急停：在最高點翻轉平面，Poi繞環一圈後從圓的另一面落下。","goodFor":"從急停做出立體環繞。","alignmentCues":["在急停的最高點轉動手腕。","保持繩子繃緊。"],"props":["單隻Poi"],"commonMistakes":["Poi還沒到最高點就翻轉了。","繩子鬆掉了。"]},"poi-arm-wrap":{"name":"纏臂","description":"Poi纏住向前伸出的另一隻前臂，繩變短轉得更快，然後再解開，回到完整的圓。","goodFor":"第一次纏繞，以及纏繞如何讓Poi加速。","alignmentCues":["保持支撐臂靜止且持平。","讓轉動的手保持在支撐臂後方。"],"props":["單隻Poi"],"commonMistakes":["支撐臂在動。","解纏方向反了。"]},"poi-leg-wrap":{"name":"腿部纏繞","description":"抬起膝蓋，讓 poi 纏繞大腿，待它解開後放下腿。","goodFor":"身體纏繞。","alignmentCues":["poi 到來時抬膝。","支撐腿保持挺拔。"],"props":["單 poi"],"commonMistakes":["抬膝太晚。","失去平衡。"]},"poi-neck-wrap":{"name":"頸部纏繞","description":"從頭頂旋轉開始，將手向下帶，讓 poi 繞到頸後纏繞，再解開後回到頭頂。","goodFor":"華麗的纏繞動作，用來銜接頭頂旋轉。","avoidIf":["使用軟頭的練習 poi；切勿用火學習頸部纏繞。"],"alignmentCues":["下巴持平，頸部拉長。","把繩索引到頸根處。"],"props":["單 poi"],"commonMistakes":["纏到了頭部。","繩索太鬆。"]},"poi-cord-wrap":{"name":"繩纏繞","description":"從蝴蝶動作開始，兩條繩索在底部互相纏繞，球頭在短繩上飛轉，隨後再解開。","goodFor":"雙 poi 之間的纏繞。","alignmentCues":["在蝴蝶底部讓兩繩相遇。","纏繞時雙手保持不動。"],"props":["一對 poi"],"commonMistakes":["雙手向外拉開。","纏繞打結。"]},"poi-toss":{"name":"poi 拋接","description":"趁 poi 向上擺動時鬆開手柄，讓它在空中旋轉，等手柄轉回來時接住。","goodFor":"拋接。","avoidIf":["用軟 poi 練習拋接，並確保周圍有足夠空間。"],"alignmentCues":["上擺時脫手。","盯住手柄，別看球頭。"],"props":["單 poi"],"commonMistakes":["脫手太晚。","抓到了繩索而不是手柄。"]},"poi-high-toss":{"name":"高拋","description":"拋得更高，在空中多轉一圈後再接住。","goodFor":"拋得更高，轉得更多。","alignmentCues":["脫手時推得更用力。","趁手柄轉回來時接住。"],"props":["單 poi"],"commonMistakes":["丟擲後向前漂移。","接住時猛抓。"]},"poi-double-toss":{"name":"雙拋","description":"兩隻 poi 按分時節奏先後丟擲，再接回旋轉中。","goodFor":"雙手拋接時機。","alignmentCues":["先丟擲一隻，再拋另一隻。","按同樣的順序接住。"],"props":["一對 poi"],"commonMistakes":["兩隻同時丟擲。","只盯著一隻 poi，丟了另一隻。"]},"shake-out":{"name":"抖手放鬆","description":"放下道具，抖動手和 forearm。讓肩膀自然下沉。","goodFor":"高強度練習之間的短暫重置。"},"breathe":{"name":"休息與重置","description":"放下道具，放鬆站立，讓手臂自然垂下。下一輪開始前稍作停頓。","goodFor":"降低心率，在掉落之後清空挫敗感。"}}`),t={"warmup-mobility":{name:`流動熱身`,description:`跟著穩定節拍放鬆手腕、肩膀、脊柱和髖部。適合在任何道具練習前使用。`,focus:`熱身 · 靈活性`},"first-throws":{name:`第一次拋接`,description:`一個球在眼高處從一隻手劃弧到另一隻手，然後是所有模式都由此生長的雙球交換。`,focus:`雜耍 · 基礎`},"cascade-builder":{name:`Cascade 構建`,description:`雙球交換連續進行，直到第三個球加入：短 cascade 連跑、重置、再跑。`,focus:`雜耍 · 基礎`},"juggling-tempo-ladder":{name:`Cascade 節奏階梯`,description:`用三種節奏做 cascade，每上一級快幾拍。快速級別時把拋接放低。`,focus:`雜耍 · 節奏`},"siteswap-sampler":{name:`Siteswap 取樣`,description:`從 cascade 進入 423、441 和 531，並用 reverse cascade 和 shower 作為過渡清口。每個模式都從 cascade 開始並回到 cascade。`,focus:`雜耍 · 套路`},"four-ball-session":{name:`四球練習`,description:`每隻手兩球，先練四球噴泉，再練同步噴泉。`,focus:`雜耍 · 數量`},"juggling-combo-flow":{name:`雜耍組合流暢`,description:`一段長流暢組合：cascade、反向 cascade、Mills mess，以及把 siteswap 串成一首完整的音樂。`,focus:`雜耍 · 組合`},"cascade-tricks":{name:`瀑布式技巧`,description:`網球、半淋浴和爪接，每一種都能切入連續的瀑布式，再切回原樣。`,focus:`雜耍 · 變化`},"juggling-body-throws":{name:`繞身拋接`,description:`腿下拋、背後拋、切球和企鵝式：把瀑布式繞著身體拋。`,focus:`雜耍 · 繞身拋接`},"sync-shapes":{name:`同步圖形`,description:`縱列、彩虹交叉、盒式和悠悠球：三個球，每次同時拋兩個。`,focus:`雜耍 · 同步模式`},"club-foundations":{name:`雜耍棒基礎`,description:`單轉、雙棒交換和三棒瀑布式，最後以平拋收尾。`,focus:`雜耍 · 雜耍棒`},"passing-with-a-partner":{name:`與搭檔傳接`,description:`面對搭檔傳接：先傳一個球，再各持兩球，然後練六拍、四拍和兩拍。`,focus:`雜耍 · 傳接`},"club-passing-session":{name:`雜耍棒傳接`,description:`先用雜耍棒四拍熱身，再用兩拍和三拍找節奏，然後練雙傳。`,focus:`雜耍 · 雜耍棒傳接`},"hoop-juggling-session":{name:`呼啦圈雜耍`,description:`全尺寸呼啦圈立著拋接：單拋、交換、瀑布式及其反向。`,focus:`雜耍 · 呼啦圈`},"staff-first-spins":{name:`第一次轉棍`,description:`先在身體旁邊做輪轉，再做前轉。慢而均勻，每拍一轉。`,focus:`棍 · 基礎`},"staff-foundations":{name:`棍的基礎`,description:`輪轉、前轉、8 字和手對手傳遞，跟著節拍連起來。`,focus:`棍 · 基礎`},"staff-flow-weave":{name:`棍的流動編織`,description:`8 字接蝴蝶、單手轉和直升機，連起來讓棍一刻不停。`,focus:`棍 · 流動`},"staff-isolation-lab":{name:`棍的 isolation 實驗室`,description:`用更慢的速度練 isolation 和 antispin flower，中間穿插背後傳遞。`,focus:`棍 · 技術`},"staff-advanced-flow":{name:`棍的高階流動`,description:`把所有動作匯成一段長練習：編織、纏繞、isolation 和頸部滾棍。`,focus:`棍 · 流動`},"staff-both-ways":{name:`雙向轉棍`,description:`每個基礎旋轉都先正向再反向，再加上雙手頭頂直升機。`,focus:`轉棍 · 方向與平面`},"staff-contact-lab":{name:`接觸棍實驗室`,description:`開手與身體接觸：魚尾、方向盤、手與前臂滾轉，最後一拋收尾。`,focus:`轉棍 · 接觸`},"double-staff-session":{name:`雙棍練習`,description:`雙手各持一根短棍：同時、錯時、車輪和反向車輪。`,focus:`轉棍 · 雙棍`},"hoop-first-spins":{name:`第一次轉呼啦圈`,description:`腰部呼啦圈配合前後推，然後讓圈繞一隻手旋轉。`,focus:`呼啦圈 · 基礎`},"hoop-body-flow":{name:`呼啦圈身體流動`,description:`讓圈從腰部升到胸口、降到膝蓋，再回到腰部，全程不停。`,focus:`呼啦圈 · 身體`},"hoop-off-body":{name:`離體呼啦圈`,description:`手轉、lasso、wedgie 和傳遞，最後用 isolation 讓圈停在空間中。`,focus:`呼啦圈 · 離體`},"hoop-full-flow":{name:`呼啦圈完整流動`,description:`身體與離體結合：escalator、頸部呼啦圈和離體技巧連成一段長流動。`,focus:`呼啦圈 · 流動`},"hoop-body-zones":{name:`呼啦圈身體區域`,description:`腰部雙向轉，然後是胯部、大腿和胸部，在區域之間抬起與放下圈。`,focus:`呼啦圈 · 身上`},"hoop-tricks-session":{name:`呼啦圈技巧`,description:`側轉、硬幣翻轉、編織、一拋，再落回身上。`,focus:`呼啦圈 · 離身`},"hoop-doubles-session":{name:`呼啦圈雙圈`,description:`雙圈：映象與錯位手轉、側轉，以及腰上轉圈配合手轉。`,focus:`呼啦圈 · 雙圈`},"poi-foundations":{name:`Poi 基礎`,description:`先練單隻 poi，再加到兩隻：正向與反向牆面旋轉、身側車輪旋轉、分時和蝴蝶。`,focus:`Poi · 入門旋轉`},"poi-weave-session":{name:`Poi 編織`,description:`從分時進入三拍編織，正反兩個方向都練，然後是兩拍編織、reels 和交叉。`,focus:`Poi · 編織`},"poi-flower-lab":{name:`Poi 花式實驗室`,description:`先練延展和隔離，接著用單 poi 和雙 poi 練反旋，最後以一個順旋花式收尾。`,focus:`Poi · 花式`},"daily-mixed-flow":{name:`每日混合流動`,description:`每種藝術都練一點：cascade、轉棍和呼啦圈，中間加入換道具的靈活性動作。`,focus:`混合 · 練習`}},n=JSON.parse(`{"start-here":{"title":"從這裡開始：你的第一週流動","summary":"選一個道具，每天跟著節拍練十分鐘，讓解鎖樹告訴你下一步練什麼。","imageAlt":"3D 人物單手把一顆雜耍球從一隻手拋到另一隻手","body":["從外面看，流動藝術像魔法：球懸在空中，棍棒轉成一片模糊，呼啦圈繞著一個幾乎看不出在動的舞者旋轉。從裡面看，它們是一疊非常小的技能，每一個都能在一個下午學會，層層疊加，直到整疊看起來毫不費力。你的第一週就是關於這疊技能的最底層。","選擇一種道具開始。雜耍教時機和手眼協調；棍棒教平面和流暢的換手；呼啦圈教貫穿全身的節奏。三種都可以學，但一次學一種能讓你的注意力留在有進步的地方。獎勵樹展示了每種藝術的每一個動作，從第一次拋接或旋轉到高階套路，並在你掌握基礎後解鎖下一個。","少量多次地練習。每天十分鐘專注練習勝過週日練一小時，因為協調性是在兩次練習之間鞏固的，尤其是在睡眠中。從套路頁面選一個短套路、熱身、再數著拍子練幾步當前動作，就是一次完整的練習。","從第一天起就跟著節拍練習。SynthFlow 中的每個動作都按小節計數，配合相應的音樂或生成的打擊樂。當道具不聽話時，節拍給你一個可以抓住的東西，它也讓進步可衡量：這周在 90 BPM 下乾淨完成，下週 100 BPM。","做好掉道具的準備。每個人都會掉，包括排練中的專業人士。掉落告訴你哪個拋接或接住需要關注；它和天賦無關。撿起道具，等下一個強拍，再來一次。到週末你就會有一個不用思考就能做的動作，那就是流動開始的時刻。"]},"counting-and-the-beat":{"title":"計數、小節和節拍","summary":"為什麼每個動作都按小節計數，以及如何讓你的拋接和旋轉鎖在音樂上。","imageAlt":"3D 人物雜耍三球 cascade，手上方畫有弧線","body":["音樂由節拍組成，節拍組合成小節，通常每小節四拍。流動動作由迴圈組成：每隻手拋一次、棍棒轉半圈、呼啦圈繞一圈。當一個迴圈落在節拍上，動作和音樂就合為一體。這就是為什麼 SynthFlow 用小節而不是秒來衡量每個套路步驟，也是為什麼每個動作都說明一個迴圈佔幾拍。","在三球 cascade 中，每次拋接都落在一拍上，左右交替。在棍棒前旋中，半圈通常佔一拍。在放鬆的節奏下，腰部呼啦圈通常是每拍繞一圈。播放器中的計數說明了每一拍發生什麼，3D 人物和音訊在同一時鐘上移動，所以你可以跟著複製。","速度用每分鐘節拍數（BPM）衡量。每個動作都有一個舒適範圍：慢到能保持乾淨，快到道具能保持動量。低於這個範圍，旋轉道具會停滯，拋接會高到飄走；高於這個範圍，你會開始趕拍並掉落。當某個步驟超出其動作範圍時，構建器會提醒你。","每個步驟都從強拍開始，也就是小節的“一”。預備拍給你一小節讓道具動起來，然後計數小節才開始。如果你丟了節拍，不要追它：停下來，聽下一個“一”，再重新進入。音樂家把這叫做找到小節的開頭，對流動藝術家也同樣有效。","幾次練習中大聲數拍比看起來更有幫助。一邊雜耍一邊說“一、二、三、四”會把節奏和你的呼吸、聲音綁在一起，所以當套路變難時它還能存在。一旦計數活在身體裡，就在設定中關閉語音計數，讓音樂帶著你走。"]},"tempo-ladders":{"title":"速度階梯：慢就是穩，穩就是快","summary":"從你能幹淨完成的速度開始，每次提升幾個 BPM，一旦動作變形就退回來。","imageAlt":"3D 人物在牆平面中於身體前方旋轉棍棒","body":["速度階梯是同一個動作在逐漸升高的速度下重複：80 BPM 八小節，88 八小節，96 八小節，以此類推。這是讓動作變快而不變亂的最可靠方法，幾個內建套路就是圍繞它構建的。","從你能幹淨完成的一級開始，即使它感覺太簡單。最底層的意義不是挑戰；而是排練正確動作，讓正確動作成為加速的東西。每次提升一點點，大約百分之五到十。跳太多會改變動作：拋接變低、旋轉變淺，你最終練的是另一個技巧。","動作變形時就停止攀升，而不是掉道具時才停。注意早期跡象：最高點變得不均勻、棍棒偏離平面、呼啦圈上下移動。這些就是退回一級再跑一次的提示。在略低於極限的速度下乾淨完成階梯，會讓身體學會那個速度；以崩潰結束，教會的則是崩潰。","對旋轉道具來說，慢速比看起來更難，因為道具的動量更少，難以帶它透過。如果棍棒或呼啦圈在最低範圍停滯，保持速度並稍微放大動作，或者跟著音樂用半速：每兩拍一個迴圈。","在進度中記錄每個動作的最高幹淨速度。看著這個數字在幾周內慢慢上升是很好的動力，它也顯示某個動作何時停滯，需要不同的練習而不是重複同樣的東西。"]},"siteswap-notation":{"title":"Siteswap：用數字寫雜耍","summary":"每個數字表示一個球多少拍後再次被丟擲；奇數交叉，偶數留在原手，平均值就是球數。","imageAlt":"3D 人物雜耍 siteswap 441，兩次高拋和一個快速 zip","body":["雜耍套路很難用語言描述，卻很容易用數字描述。Siteswap 由劍橋、加州理工和聖克魯斯的雜耍者在 1980 年代中期獨立發展出來，把一個套路寫成一串重複的數字。雜耍者用它分享套路、檢查一個想法是否可行，並發現沒人嘗試過的技巧。SynthFlow 用它從同一個引擎為每個雜耍套路製作動畫。","想象雙手在每一拍交替丟擲：右、左、右、左。Siteswap 中的每個數字表示這一拍丟擲的球會在多少拍後再次被丟擲。3 會在三拍後回來；因為三是奇數，它落到另一隻手。三球 cascade 就是永遠的 3、3、3、3，簡寫為 3。4 會在四拍後回到同一隻手，這就是四球 fountain。","小數字有特殊含義。2 會在兩拍後回到同一隻手，實際意味著把球拿一會兒。1 會在下一拍交叉到另一隻手，一個快速 zip 直接橫穿。0 是空手。更大的數字是更高的拋接：5 是一個高高的交叉拋。","一個數字一個數字地讀套路。在 441 中，兩次拋接留在各自一側，而第三個球從下面快速穿過。在 531 中，一個高交叉拋升起，同時一個 cascade 拋和一個 zip 讓另外兩個球繼續運動。在 423 中，一個 fountain 高度的拋、一個拿住的球和一個 cascade 拋輪流出現。","平均值定理告訴你一個套路需要多少球：把數字相加，再除以數字個數。441 三個數字相加為 9，所以是三球。如果平均值不是整數，這個序列就無法雜耍。第二個檢查是同一拍不能有兩個球落在同一隻手，這就是雜耍者在嘗試前發現不可能套路的方法。","Siteswap 也有雙手同時拋的記法，寫在括號裡，如 (4,4)，以及一隻手同時拋兩個球的記法，寫在方括號裡。你不需要這些也能雜耍得很好，但一旦數字開竅，每個新套路名字都會開始自我解釋。開啟流動詞彙表檢視各個數字。"]},"passing-basics":{"title":"傳接基礎：與搭檔一起雜耍","summary":"面對搭檔，兩人右手同時丟擲，直線傳到對方左手，邊做邊數：六拍、四拍、兩拍。","imageAlt":"兩個3D雜耍者面對面，把球直線傳給對方","body":["傳接就是和別人一起雜耍。兩名雜耍者面對面站立，各自做著瀑布式拋接，時不時把其中一個拋物傳給對方，而不是拋給自己。這是雜耍中最具社交性的玩法之一：許多雜耍者的雜耍節夜晚就是在雜耍棒傳接中度過的，它讓練習變成一場對話。","傳球時兩人相距約兩米半，傳雜耍棒則稍遠一些。兩人按同一個口令開始雜耍，右手同時丟擲。標準傳接走直線：球從你的右手離開，落進正對面搭檔的左手。不是朝對方臉上扔。瞄準對方的左胯，讓球劃出一道弧線，最高點略高於頭頂，正好落在兩人中間。","傳接模式按傳接的頻率命名。六拍是每第六拋傳一次，中間隔著五個自拋來穩住節奏。四拍是標準熱身，每隔一次右手拋就傳一次：傳、自拋、自拋、自拋。兩拍中每次右手拋都是傳，每次左手拋都是自拋。三拍的傳接左右手交替，所以你也要學會用左手傳。Ultimates（一拍）則讓每一次拋都變成傳。","一開始要一起大聲數拍。“傳、二、三、四”能讓兩人保持同一節拍，只要有一人亂了拍子，傳過來的球就不會準時到達。SynthFlow 的數拍語音會在傳接時說“傳”，在其他拋接時說“自拋”，並且都落在節拍上，這樣你就能獨自練習時機，螢幕上的搭檔會陪你一起雜耍。","先從一個球開始。把它傳過去，讓搭檔用左手接住、換到右手，再傳回來。然後各拿兩個球，右手同時傳接，把接到的球從左手換到右手再傳出去。之後才加入瀑布式拋接。大多數傳接掉球都是因為傳得太遠或太低平，而這兩個問題用一個球比用六個球更容易修正。","在 SynthFlow 記譜中，傳接模式會列出你和搭檔的拋接，每拍一個，用 p 標記傳接：四拍是 <3p 3 3 3|3p 3 3 3>。數字的含義與 siteswap 相同。4p 是晚一拍落下的雙傳，七棒模式就是這樣構建的。"]},"planes-and-geometry":{"title":"平面：牆平面、輪平面和地面平面","summary":"旋轉道具生活在平坦的平面中；保持平面乾淨是讓棍棒或呼啦圈看起來利落的大部分原因。","imageAlt":"3D 人物在身體兩側以 8 字編織棍棒","body":["旋轉的棍棒或呼啦圈會掃出一個平坦的表面，稱為它的平面。流動藝術家描述相對於身體的三個基本平面。牆平面在你面前，像一塊你可以把手掌按上去的玻璃。輪平面在你身旁，像車輪沿著你的側面轉動。地面平面是水平的，與地面平行，比如頭頂直升機或套索。","乾淨的平面是觀眾讀作技巧的東西。一根偏離平面搖晃的棍棒看起來不確定，即使它從不掉落；一個在傳遞中保持完全平坦的呼啦圈看起來毫不費力。大多數早期練習其實都在悄悄練平面：不讓手腕扭轉、不讓手肘外張，讓肩膀而不是手來移動道具。","許多技巧的定義就是改變平面。8 字編織把棍棒從一側的輪平面移到另一側的輪平面。butterfly 把它折到肩後再回來。escalator 讓呼啦圈沿身體上下移動，同時它的平面保持水平。學習每個動作在空間中從哪裡開始、到哪裡結束，是把它們連線成流動的方法。","3D 檢視器可以在你練習時畫出平面。學習新旋轉時開啟它並比較：你的棍棒頂部是否向你傾斜？呼啦圈前方是否下沉？鏡子或手機攝像頭也能顯示同樣的事情。從側檢視觀看對牆平面動作特別有用，因為從正面看不到傾斜。","平面也有助於安全和空間。練習前，檢查你將使用的每個平面是否清空：前面的牆、身旁的牆，以及地面平面和頭頂動作上方的天花板。一個乾淨、沒有障礙的平面就是自信的平面。"]},"spin-and-antispin":{"title":"旋轉、反旋轉和 isolation","summary":"道具相對於手的轉動方式產生了三類動作：旋轉、反旋轉和 isolation。","imageAlt":"3D人物用棍畫出一朵四瓣antispin花","body":["當你讓旋轉的道具繞圈移動時，會同時發生兩種旋轉：你的手繞著一個圓移動，而道具繞著自己的中心轉動。Flow理論根據這兩種旋轉的關係來命名動作。棍、呼啦圈和poi用的是同一套詞彙，所以技巧在不同道具之間遷移得如此順暢。","在spin（有時叫inspin）中，道具的轉向與手的圓周方向相同。這是自然方向；大多數人的第一次旋轉就是inspin，只是沒人這麼叫它。畫出的形狀是一朵花瓣朝外的花。","在antispin中，道具的轉向與手的圓周方向相反。一開始感覺很怪，就像一手拍頭一手揉肚子，但它能畫出經典的花瓣花。花瓣的數量取決於道具每轉一圈手轉幾次：每圈三次反向旋轉得到四片花瓣，也就是棍技巧樹中的四瓣antispin。","isolation是一種特殊情況：手繞圈的方式讓道具上的某一點看起來凝固在空間中。用棍時，中心保持不動，兩端繞著它掃過；用呼啦圈時，圈的中心或邊緣上的某一點保持不動。isolation看起來像道具在漂浮，而身體在繞著它轉。它們要求精確的手部軌跡，因此是訓練其他所有技巧的絕佳方式。","慢慢學這些，跟著節拍來。antispin尤其適合用遠低於你正常旋轉速度的節奏來練，用數拍來標出道具應該在的位置：上、側、下、側。用3D檢視器裡的ghost看下一拍的位置，用trail看你的花花瓣是否均勻。","當spin、antispin和isolation在一個平面裡變得熟悉後，試試在另一個平面裡做。理論是一樣的，你的身體會學到平面只是一個設定，這是邁向即興flow的一大步。"]},"sequencing":{"title":"flow套路是如何構建的","summary":"熱身，圍繞一個重點練習並用能順暢銜接的動作連線，保持節奏跳躍幅度小，最後用輕鬆的冷卻收尾。","imageAlt":"3D人物在身前用雙手傳遞呼啦圈","body":["一個好的flow套路和一場好的音樂演出有相同的形狀：一個暖場的開場，一個層層推進的中段，和一個讓所有人喘口氣的結尾。SynthFlow內建的套路遵循這個形狀，構建器的co-pilot會對照它檢查你的套路。","以熱身開場。手腕繞環、手臂繞環和肩部繞環讓你將要負荷的關節在溫和的節奏下走完全程。短時練習兩三分鐘就夠了；更長的練習和寒冷的日子需要更多。","給練習塊一個重點。選一個你正在練的動作，用能銜接進它的動作把它圍起來。構建器會顯示每一步如何與上一步連線：從相同的手部位置直接順暢銜接、小幅重新握持、放下道具，或建立在之前技巧之上。能順暢銜接的套路感覺像跳舞；充滿放下的套路感覺像清單。","保持步驟之間的節奏變化小。從80跳到130 BPM會重置你的節奏感並招來掉落。co-pilot會標記超過約四分之一的跳躍，把半速和倍速摺疊起來，這樣70 BPM的呼啦圈步驟可以挨著140 BPM的曲目。","不止一次回到重點動作。在一次練習中反覆回到它，中間穿插其他動作，比一個長塊練得更好，因為每次迴歸都是從略微不同的起點做一次全新的嘗試。","以冷卻收尾：一個慢節奏的輕鬆動作，或短暫休息配合幾次呼吸。它讓心率降下來，給你的協調一個平靜的結尾去記住。播放前預覽套路，刪掉任何明顯是昨天野心的東西。"]},"effort":{"title":"什麼時候該推節奏","summary":"當動作穩定且你精力充沛時推；當峰值搖晃、握持變緊或掉落開始扎堆時放緩。","imageAlt":"3D人物用高cascade雜耍五個球","body":["flow的進步來自在能力邊緣練習，但邊緣會移動。有些天它比你預期的更遠；有些天它退回去了。學會讀懂它是一種和任何技巧一樣值錢的技能。","當基礎穩固時推。如果你的峰值均勻、棍保持在它的平面裡、呼啦圈保持水平、呼吸輕鬆，就上節奏階梯的下一級，或試試進階裡的下一個練習。一次練習的前十五分鐘，熱身之後，通常是練新內容的最佳時機。","當質量下滑時放緩。扎堆的掉落、握持變緊、肩膀往耳朵方向縮、屏住呼吸，都在說你的神經系統累了。降節奏，回到一個你掌握的動作，或結束練習。硬撐過疲勞大多是在排練錯誤。","也要留意身體的警告。重複的拋接和旋轉會給手腕、前臂和肩膀帶來負荷。一天內消退的痠痛是正常的適應。尖銳的疼痛、練習中加重的疼痛、麻木或刺痛是停下來休息的理由；持續的症狀值得看醫生。","每次練習後用努力評分。練習嚮導會讀它：連續幾次高強度練習，它就建議溫和一些；連續幾次輕鬆練習，它就建議多一點。誠實的評分帶來更好的建議。"]},"drops-are-data":{"title":"掉落是資料","summary":"掉落告訴你該修哪個拋或接；把它當成失敗只會教你緊張起來。","imageAlt":"3D人物在雙手之間交換兩個雜耍球","body":["每個雜耍者都有過地上鋪滿球的時候。每個棍旋轉者都聽過嘩啦聲。持續進步的人和放棄的人之間的差別很少是天賦；而是他們如何對待掉落。","掉落是一次測量。它告訴你哪個丟擲了問題、哪個接你伸手去夠、旋轉的哪個瞬間失去了平面。如果同一個球總是落在你前面，你的拋在往前漂。如果掉落出現在六次拋之後，你的第三或第四次拋有問題。觀察在哪裡和什麼時候，然後選一件事去改。","把掉落當成失敗是有代價的。恐懼讓肩膀變緊、呼吸變短，而緊張讓動作變小變快，這會導致更多掉落。平靜的回應——撿起來、呼吸、等下一個重拍、重新開始——不只是愉快；它是技術上正確的回應。","數乾淨的連做，而不是掉落。SynthFlow在你積累足夠的乾淨連做和練習分鐘數後掌握一個動作，所以一路上的掉落只是分鐘數的一部分。有些天你會記錄十次乾淨連做，有些天兩次。兩天都算數。","有時故意掉落。學一個新技巧時，練第一次拋或前半圈旋轉，然後讓它掉。然後再加接。把有風險的瞬間單獨拿出來會縮小它，你會學到地板不是你的敵人。它只是你學習時道具會去的地方。"]},"safety":{"title":"安全：空間、道具和紅旗訊號","summary":"清空你的平面，選擇寬容的道具，熱身，遇到尖銳疼痛、麻木或頭暈就停下。","imageAlt":"3D人物在頭頂平轉棍，周圍空間清空","body":["與大多數運動相比，flow arts風險很低，但道具移動很快，飛得比你預期的遠。幾個習慣能讓練習對你、你附近的人和傢俱都安全。","開始前清空你的空間。檢查你將用到的每個平面：前方、兩側和上方。棍和呼啦圈需要的空間比你想象的多，通常每個方向至少是臂展加道具長度的一個圓，伸手可及處沒有易碎品。室內，注意吊燈和風扇；室外，注意不平的地面和路人。","學習時用寬容的道具。豆袋雜耍球不會滾遠。有襯墊或泡沫端的棍打到頭時沒那麼疼，而它一定會打到。更大更重的呼啦圈轉得更慢，更容易保持。等基礎變成自動的，再升級到更快或更炫的道具。","每次練習前熱身，逐漸增加量。拋接和旋轉是重複性的，而對冷組織施加重複負荷是手腕和手肘痠痛的常見原因。如果你突然增加大量練習，也要增加休息日。","遇到紅旗訊號就停下：尖銳或電擊般的疼痛、手部麻木或刺痛、繼續練會加重的疼痛、頭暈，或頭部受擊後有任何持續症狀。頸部動作和contact rolls需要格外小心；用有襯墊的道具慢慢學它們。","本應用教授的是技巧，不是醫療護理。懷孕、近期受傷、關節問題以及任何讓你擔心的情況，都應在增加新負荷前諮詢合格的專業人士。火焰表演是一門獨立的學科，有其自身的安全訓練；SynthFlow 不教授火焰表演。"]},"warm-up":{"title":"為什麼熱身對道具練習很重要","summary":"兩到五分鐘的手腕、手臂、肩膀和髖部靈活性練習能讓旋轉更順暢，也能保護你的關節。","imageAlt":"3D 人物雙臂前伸，緩慢轉動手腕","body":["Flow 練習看起來溫和，但對少數幾個關節的要求很高。雜耍會重複同一個拋接上千次；棍棒旋轉會讓手腕轉遍整個活動範圍；呼啦圈每轉一圈都會晃動脊柱和髖部。溫暖的軟組織比冰冷的軟組織更能承受這種重複。","好的 flow 熱身簡短而有針對性。雙向手腕繞環能準備好承擔大部分工作的關節。手臂繞環和肩部繞環能喚醒肩袖和肩胛骨，它們控制著每一次旋轉的平面。髖部繞環和軀幹扭轉對呼啦圈最重要。頸部半圓繞環——絕不要完整繞圈——能緩解一直抬頭看圖案帶來的緊張。","跟著節拍慢慢動。SynthFlow 中的熱身步驟和其他所有內容一樣按拍計數，節奏放鬆，所以練習的前幾分鐘也在調整你的時機感。等道具拿出來時，你已經跟著音樂動起來了。","用半速的道具動作結束熱身。幾次慢速拋接、一個懶散的前旋或一個大而慢的呼啦圈繞環，能把靈活性練習和你即將練習的動作連線起來，也能告訴你今天身體的感覺如何。","熱身也是一種心理過渡。每次練習開始時同樣的三分鐘，會成為練習已經開始的訊號。忙碌的日子裡，熱身有時就是全部練習，那也算數。"]},"anatomy-basics":{"title":"道具背後的身體","summary":"前臂抓握與釋放，肩膀引導平面，核心讓你保持穩定：一份通俗易懂的 flow 身體地圖。","imageAlt":"3D 人物在腰部轉呼啦圈，上半身放鬆","body":["你不需要懂解剖學才能雜耍，但一張簡單的地圖能幫你理解什麼會疲勞、該熱身什麼、該休息什麼。Learn 的肌肉部分有一個互動模型；這篇文章是簡短導覽。","前臂承擔大部分精細工作。手掌側的肌肉負責合攏手指和屈腕；前臂背側的肌肉負責張開手指和伸腕。接住和釋放、握住棍棒再讓它滾動，都發生在這裡。前臂疲勞是長時間練習後最常見的感覺，這也是為什麼放鬆握持是這麼常見的提示。","肩膀負責引導。三角肌抬起手臂；肩袖——關節周圍的四塊小肌肉——在上臂移動時保持它居中。肩胛骨周圍的肌肉讓整個系統保持穩定。當棍棒偏離它的平面時，原因往往是肩膀，而不是手。","核心讓你保持安靜。在雜耍中，穩定的軀幹能防止圖案漂移。在呼啦圈中，腹部和背部肌肉透過小幅前後脈衝驅動呼啦圈。髖部和腿是你的底座：柔軟的膝蓋吸收動作，讓你在不干擾道具的情況下轉移重心。","你的眼睛和內耳也很重要。雜耍訓練你去看最高點，而不是手；旋轉訓練你的平衡。短時間練習加休息能讓兩者適應而不頭暈。把這張地圖當作基礎知識，而不是診斷；如果疼痛持續不退，請諮詢專業人士。"]},"biomechanics-safety":{"title":"手腕、肩膀與重複負荷","summary":"放鬆握持、中立手腕和循序漸進的總量，能讓承擔全部工作的關節保持舒適。","imageAlt":"3D 人物用一隻手在手臂上方旋轉棍棒","body":["Flow 受傷很少是戲劇性的。幾乎總是過度使用：重複太多、握得太緊、休息太少。好訊息是，同樣的幾個習慣就能預防大多數問題。","放鬆握持。雜耍球只需要剛好留在手裡的壓力；棍棒只需要一圈鬆散的指環讓它滾動。緊握會讓前臂肌肉疲勞，並給肘部肌腱增加負荷。如果幾分鐘後指節發白或前臂灼燒，就放鬆並降低節奏。","儘可能讓手腕接近中立。旋轉會讓手腕經過大幅活動範圍，適度是沒問題的。長時間把它們保持在活動範圍末端，或強迫僵硬的手腕轉動，才會刺激它們。讓肘部和肩膀分擔動作。","讓肩膀工作，但不要聳起。大圈來自肩關節；聳起的肩膀會夾擠並很快疲勞。用鏡子或相機模式檢查肩膀是否保持下沉，尤其是在 helicopter 和 lasso 這類過頂動作中。","循序漸進地增加總量。如果你通常練二十分鐘，不要因為節日快到了就跳到兩小時。每週適度增加總時間，並至少保留一天輕鬆練習。換道具來分散負荷：呼啦圈練習能讓雜耍疲勞的前臂休息。","一天內消退的疼痛是正常適應；持續、加重或伴隨麻木的疼痛則不是。休息、減少總量，如果持續就尋求專業建議。這是教育內容，不是醫療建議。"]},"choosing-props":{"title":"選擇你的第一套道具","summary":"雜耍用豆袋球、一根輕的帶襯墊棍棒和一個大號成人呼啦圈，會讓最初幾周輕鬆得多。","imageAlt":"3D 人物在一隻手周圍旋轉呼啦圈","body":["好的初學者道具能讓學習更快、更少挫敗。你不需要昂貴裝備，但幾個選擇很重要。","雜耍方面，從三個約 60 到 130 克的豆袋球開始。豆袋球掉落後不會彈跳或滾走，能省下很多追球的時間。它們應該能舒適地放在手掌中。更大的舞臺球和有彈性的矽膠球適合以後再用。同色有助於看清圖案；三種不同顏色有助於你在學習 siteswap 時追蹤單個球。","棍棒方面，初學者旋轉棍通常大約 1.2 到 1.5 米，輕，兩端有襯墊或橡膠。粗略參考：豎立時它應該到你的胸部和肩膀之間。更長、更重的棍棒在掌握基礎後轉得更慢、更順，但起步更難，打到你也更疼。中間有握把會有幫助。","呼啦圈方面，從比你想象中更大、更重的開始。成人初學者呼啦圈立在地上時通常到腰部和胸部之間。更大的呼啦圈旋轉更慢，給你時間找到腰部呼啦圈的節奏。等你能舒適完成後再用更小、更輕的呼啦圈做快速離身技巧。","無論你選什麼，都要確保動作的節奏範圍適合道具。更重的道具通常適合更低的節奏。如果應用裡舒適的範圍配上你的道具感覺太趕，就在構建器裡設定自己的節奏；計數會跟著走。"]},"practice-at-home":{"title":"在家和公園練習","summary":"每天短時間練習、清出空間、用床或沙發邊緣接掉落，有機會就去公園一起玩。","imageAlt":"3D 人物在練習輪次之間甩動手臂放鬆","body":["大多數 flow 藝術家都在家學習，一次幾分鐘。稍微佈置一下，會讓在家練習更容易開始，也更容易堅持。","找到你的位置。雜耍時，站在床或沙發前意味著掉落的球會落在腰部高度，而不是滾到傢俱下面，也能防止你一直往前走。棍棒和呼啦圈則找你擁有的最大空地，檢查天花板，並移走易碎物品。大旋轉更適合花園或公園。","讓道具看得見。桌上的球會在通話和燒水間隙被拿起來雜耍；門邊的呼啦圈會被用。開始所需的力氣越小，你就越常練。五分鐘的例行練習也算數，一天幾次短練習會很快累積起來。","把應用當作框架。選一個套路，或讓嚮導推薦一個，完整練一遍，然後記錄你的努力。像《從零到Cascade》這樣的短課程給每週一個明確目標，讓你不會在技巧之間漂移。","有機會就和別人一起練。許多城市都有雜耍俱樂部、馬戲學校和公園flow聚會。看比你領先一步的人練，往往能解決教程解決不了的問題；教比你落後一步的人，會讓你自己的技術更清晰。帶上你的道具，問問大家在練什麼，分享計數教會你的東西。"]},"learning-with-the-app":{"title":"用3D教練學習","summary":"放慢、映象、開啟殘影和軌跡、切換鏡頭，並用攝像頭模式獲取反饋。","imageAlt":"3D人物表演staff isolation，軌跡顯示路徑","body":["SynthFlow中的每個動作都以3D動畫呈現，並與音樂共用同一個時鐘，所以人物始終精確踩在節拍上。用得好，這個檢視器就是一位耐心的老師，永遠不會厭倦向你展示同一個拋接。","先放慢。每個動作的進階階梯從慢速和區域性版本開始，然後只用手，最後是踩拍完整動作。半速能保持時值關係不變，同時給你的眼睛留出跟隨的時間。","如果你面對老師學得更好，就映象人物；當一個視角遮住某些東西時，就切換鏡頭。側檢視能顯示staff傾斜和拋接漂移；俯檢視能顯示hoop平面和直升機路徑。軌跡畫出每個道具去過哪裡，把一團模糊變成可以研究的形狀。殘影顯示道具在下一拍會到哪裡。","注意常見錯誤。每個動作都能展示典型問題，比如向前漂、高度不均或搶拍，讓人物故意做錯，並給出糾正提示。在模型上認出錯誤，會更容易在自己的身體裡感覺到它。","攝像頭模式會給你反饋。經允許後，它會在你練習時追蹤你的手和身體，並把你的時機與節拍比較。處理在你的裝置上進行。它並不完美，光線好會有幫助，但即使只是粗略反饋你是早了還是晚了，也很有價值。","最後，有時要關掉檢視器。只跟著音樂練習，相信計數。目標是做出一個完全不用看任何東西也能完成的動作。"]},"music-for-flow":{"title":"找到合適的音樂","summary":"測量過的速度、半速和倍速、生成的打擊樂，以及你自己的曲目，都能讓計數保持準確。","imageAlt":"3D人物在胸前轉hoop，雙臂抬起","body":["音樂能把練習變成flow，但前提是音樂裡的節拍就是計數里的節拍。118 BPM的曲目配120 BPM的套路，一分鐘內就會漂開，最後你是在和音樂對抗，而不是乘著它。","SynthFlow自帶的曲目都有測量過的速度和強拍，所以播放器可以讓每一步從音樂的“一”開始，並保持計數對齊。構建器會優先列出適合某一段速度的曲目，包括半速或倍速曲目：140 BPM的曲目完全可以承載70 BPM的hoop步驟。","生成的打擊樂適用於任何速度。為某一段選擇一套鼓組，播放器就會合成完全匹配的節拍，無論你是在做速度階梯還是慢速訓練。當你想要脈衝而不想讓旋律拉走注意力時，這也是最好的選擇。","你可以分析自己裝置裡的曲目。應用會估算速度和強拍，並讓你跟著拍打來檢查。帶有穩定電子或原聲脈衝的曲目效果最好；速度變化、自由節奏或長前奏的音樂更難測量，也更難用來練習。","計數練習期間會關閉影片流，因為它的時機無法被精確控制。改在熱身或自由練習時使用它，那時不需要任何東西對齊。"]},"plateaus":{"title":"平臺期和漫長的中段","summary":"每個flow藝術家都會遇到毫無進步的幾周；先改變訓練、速度或道具，再改變目標。","imageAlt":"3D人物雜耍Mills Mess，雙臂交叉","body":["flow的開頭很美妙：每次練習都有新東西。然後，往往在你能夠穩定雜耍cascade或讓hoop一直轉下去的時候，進步似乎停止了。這個漫長的中段是大多數人放棄的地方，也是最有趣的學習發生的地方。","平臺期通常是鞏固期。你的神經系統正在重組動作，讓它需要更少注意力，而這不會表現為新技巧。一個卡了兩週的技能，常常會在某天早上突然出現。穿過平淡期繼續練。","改變訓練，而不是目標。如果cascade無法更快，就用更低的速度練，追求完美的頂點，然後眼睛盯著圖案上方一點，再然後只用一隻手。如果某個staff動作出不來，就把它拆成兩半，各自踩拍訓練。新的訓練會給你的大腦關於同一技能的新資訊。","交叉訓練。學習第二種道具常常會解鎖第一種。Hoop能改善雜耍背後的節奏；staff訓練會教給你讓hoop技巧幹淨的平面。每種藝術的獎勵樹都是獨立的，所以多樣性從不會犧牲進度。","對此溫柔一點。和上個月的自己比，而不是和網上練了十年的表演者比。進度頁面會誠實記錄分鐘數、最高速度和已掌握動作。在平淡的一週，看看它，看看這條線已經爬了多遠。"]},"history-of-juggling":{"title":"雜耍簡史","summary":"從埃及墓室壁畫到中世紀jongleurs、雜耍劇場和現代數學。","imageAlt":"3D人物在圓圈中雜耍三球shower","body":["雜耍非常古老。已知最早的影象之一，是埃及貝尼哈桑一座中王國時期墓室裡的壁畫，大約四千年前，描繪女性拋球。來自中國、希臘、羅馬和太平洋地區的記載與影象表明，許多文化中的人都找到了拋接以作展示和玩樂的方式。","在中世紀歐洲，jongleur這個詞——也就是“juggler”的來源——描述的是唱歌、講故事、表演雜技和拋接物品的巡迴藝人。雜耍只是眾多技能之一，是表演者工具箱的一部分，而不是一門獨立的藝術。","十九世紀和二十世紀初的雜耍劇場與馬戲團讓雜耍成為主打節目。表演者開始專精：戴帽持杖的紳士雜耍者、club雜耍者，以及向七球、八球甚至更多推進的數量雜耍者。二十世紀初的Enrico Rastelli至今仍常被稱為最偉大者之一。","從1970年代起，圍繞俱樂部、節慶和大會興起了業餘雜耍文化，人們自由分享技巧。1980年代數學加入進來，siteswap記法讓雜耍者能把圖案寫成數字，從而在任何人真正丟擲來之前，就在紙上發現了新技巧。","今天，雜耍處在馬戲、運動、舞蹈和數學的交匯點。有些雜耍者比數量和耐力，有些隨音樂表演編舞，還有些純粹為探索圖案而探索。每條路都從同樣的兩球交換開始，而這周你就能學會。"]},"history-of-staff":{"title":"Staff spinning：從武器到flow","summary":"武術staff、baton twirling和火焰表演都滋養了現代spin staff。","imageAlt":"3D人物在肩後表演staff butterfly","body":["Staff是現存最古老的工具之一，旋轉它也是一項古老技能。許多武術傳統都用長staff訓練，其中包括沖繩bō、中國gun和歐洲quarterstaff格鬥，它們的訓練包含快速旋轉和換手，用於防禦和展示。","表演旋轉還有其他根源。Baton twirling在二十世紀發展成一項競技 discipline，其中的拋接、滾動和旋轉至今仍被spinners借用。世界各地的劇場、遊行和街頭表演，早在有人稱之為flow之前，就使用旋轉的棍棒和長杆。","現代flow staff（流動棍）場景與火焰表演和節日文化一起，從二十世紀後期發展起來。兩端帶芯的火焰棍讓旋轉在黑暗中可見，並推動這門藝術走向流暢、連續的運動，而不是擊打。後來LED棍把同樣的視覺效果帶到了室內。","大約同一時期，flow藝術家們開始用共同的理論來描述旋轉：平面、旋轉與antispin（反旋）、isolation（隔離）、時機和方向。其中大部分理論在poi社群中發展出來，並傳播到棍、呼啦圈和其他道具上，這也是為什麼同樣的詞會貫穿這個應用。","Contact staff（接觸棍），即棍在身體上滾動而不是被握住，發展出了自己的風格，包括在脖子、肩膀和手臂上的滾動。如今棍的旋轉從武術演示到緩慢、冥想式的contact flow，全都建立在同一個最初的輪式旋轉之上。"]},"history-of-hoop":{"title":"呼啦圈：從古老玩具到flow藝術","summary":"呼啦圈作為玩具和工具已有數千年曆史；1950年代的狂熱和節日復興讓圈舞成為一門藝術。","imageAlt":"3D人物讓旋轉的呼啦圈沿身體向上移動","body":["呼啦圈是最古老的玩具之一。古埃及、希臘和羅馬的兒童被描述或描繪為用棍子滾圈、繞身體旋轉，此後許多文化中都出現了圈類遊戲。","呼啦圈在一些傳統中也承載著深厚的文化意義。許多美洲原住民社群表演的Hoop Dance使用多個圈來構建動物和大地等形狀，透過動作講述故事。它本身就是一種活態傳統，與現代flow場景不同，值得從其自身的實踐者那裡瞭解。","1950年代末由美國批次生產的呼啦圈引發的塑膠呼啦圈狂熱，幾乎在一夜之間讓數百萬家庭擁有了呼啦圈。此後幾十年，呼啦圈大多被視為兒童玩具和健身小工具。","從1990年代末和2000年代開始，節日和線上社群中的成年圈手開始把呼啦圈當作舞伴。更大、更重的手工圈讓成年人更容易做on-body hooping，而更小的圈則開啟了快速的off-body技巧。分享的影片讓isolation、wedgie和escalator等詞彙遠遠傳播到任何一座城市之外。","現代圈舞借鑑棍和poi的理論，並從各種音樂中汲取節奏。它易上手、快樂且深奧：初學者一天就能找到腰部節奏，而高手可以花數年打磨一個isolation。"]},"fire-and-led":{"title":"火焰、LED和表演道具","summary":"表演道具會改變重量、速度和風險；先用練習道具學會每個動作，再單獨訓練火焰。","imageAlt":"3D人物像套索一樣在頭頂平轉呼啦圈","body":["夜晚看到火焰棍或LED呼啦圈，往往是吸引人們進入flow的原因。表演道具很棒，但它們和練習道具不同，過渡到它們需要一個計劃。","LED道具通常比練習版本更重，因為要裝電池和電子元件。這會改變動量：旋轉會帶得更遠，拋接感覺不同，手腕也更費力。先用練習道具學會每個動作，然後預期在LED上有一段短暫的適應期。最初幾次練習要降低速度。","火焰表演是一門獨立的 discipline。燃料處理、安全旋轉區域、帶滅火毯的安全觀察員、合適的服裝和當地規則都很重要，最好向有經驗的火焰表演者當面學習。SynthFlow不教授火焰，應用中的任何內容都不應使用點燃的道具練習。","許多flow社群採用的一條好規則是：只有當你能用練習道具穩定地連續完成很多次某個動作後，才用表演道具表演它。在燈光或火焰下，沒有實驗的餘地。","表演也會改變你編排動作的方式。觀眾能讀懂大平面、乾淨的過渡和清晰的靜止時刻。像其他routine一樣在builder中構建表演routine，預覽它們，並每次跟著同一首音樂排練，讓數拍變成編舞。"]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"cascade突然開竅的那一天","summary":"三週追著球滿地板跑，在我停止盯著手、開始數拍的那一刻結束了。","body":["有三個星期，我的三球cascade剛好只能撐四次拋接。右、左、右，然後第三個球就跑到沙發後面去了。我看影片，放慢，加速。我像每個教程說的那樣站在床前。什麼都沒變，除了我的詞彙量。","解決辦法來的時候，簡單得令人尷尬。我放了一首90 BPM的曲子，大聲數拍：一、二、三、四，每一拍拋一次。突然之間，拋接有了該去的地方。不再是手覺得準備好了就拋——也就是恐慌讓它拋的時候——每一次拋接都在等自己的拍子。pattern變慢了、變高了，也更平靜了。","第二個修正是我看哪裡。我一直盯著自己的手，這就像靠看眼皮來讀書。當我把視線抬到頂點，也就是弧線頂端的兩個點時，我的手開始自己接球。頂點告訴我拋接是否均勻；手不需要監督。","十二次拋接變成了二十次，然後五十次。一天晚上，我整整八小節沒有掉球，像個傻子一樣對著天花板笑。應用稱之為clean run。我稱之為第一次覺得juggling像音樂，而不是打架。","如果你卡在四次拋接，試試對我有效的方法：大聲數拍，跟著拍子拋，看頂點。掉球時別大驚小怪。地板是每個cascade開始的地方。"]},"why-we-count-in-bars":{"title":"為什麼我們按小節數拍，而不是按秒","summary":"四十秒的保持對拉伸很合理；juggling pattern活在拍子上，所以我們按小節來衡量練習。","body":["開始構建SynthFlow時，第一個重大決定是如何衡量routine步驟。我們的姊妹應用SynthYoga按秒和呼吸來計算保持。這對你保持的姿勢有效。但對一個隨拍子重複的pattern無效。","一次juggling拋接、一次棍的半轉和一次呼啦圈環繞都是迴圈。如果音樂是100 BPM，而你的cascade是103，你就不是在跟著音樂juggling；你是在它附近juggling，一分鐘內就會落後一拍。按小節在小節線上衡量步驟，意味著音樂、數拍、3D人物和下一步都從同一個強拍開始。","小節也讓進步變得具體。“juggling一分鐘”很模糊：一分鐘做什麼，什麼速度？“96 BPM下八小節cascade”則是一個具體、可重複的挑戰。如果你能幹淨地完成，下一次練習就可以要求104。這就是tempo ladder的工作方式，也是為什麼應用中的mastery取決於clean run，而不只是時間。","這需要認真的工程。每個動畫都由與音樂相同的音訊時鐘驅動，提前排程，所以不會卡頓。內建曲目有測量好的速度和強拍。生成的打擊樂可以填充你選擇的任何速度。來自你裝置的曲目會被分析並用tap test檢查。流媒體影片在計數練習中被關閉，因為我們無法讓它保持在同一拍上。","結果是，拍子變成了老師。當你漂移時，你能聽到。當你鎖定時，你能感覺到。按小節計數原來是我們做出的最重要的設計選擇。"]},"staff-hit-me-in-the-head":{"title":"棍打到了我的頭（以及其他教訓）","summary":"每個棍手都會被敲；護墊、平面和耐心會把敲打變成進步。","body":["我的第一個figure-8以棍彈到我的頭骨、狗離開房間結束。第二個也一樣，只是沒有狗。如果你在學棍，你會被打到。問題是有多疼，以及你從中學到什麼。","第一課：護墊不是懦弱。兩端柔軟的練習棍把疼叫變成了聳肩。聳肩很重要，因為恐懼會讓你畏縮，而畏縮的手腕會把棍拉出它的平面，導致下一次被敲。","第二課：大多數擊中來自傾斜的平面。當我從側面拍自己時，我能看到棍在每次旋轉頂部都朝我的臉傾斜。我的手腕在向內翻。3D檢視器中的平面疊加顯示了乾淨版本：棍在身體旁邊的一個平坦面中，從不向內傾。修正手腕就修正了敲打。","第三課：慢而數拍勝過快而僥倖。我把速度降到figure-8範圍的最低端，跟著音樂數“右側、左側”。在那個速度下，我能感覺到換手並保持平面平坦。一週後我就能回到原來的速度。","第四課：笑。棍旋轉既荒唐又美妙。被敲是場景中每個人共享故事的一部分。需要的話戴頂帽子，清開天花板燈，繼續旋轉。"]},"hooping-for-people-who-cant-hoop":{"title":"給那些覺得自己轉不了呼啦圈的人的呼啦圈指南","summary":"大多數“轉不了呼啦圈”的成年人拿到的是玩具大小的呼啦圈；換個大圈，加上前後脈衝，大部分問題就解決了。","body":["“我轉不了呼啦圈”是呼啦圈老師最常聽到的話，說這話的人上次嘗試通常用的是兒童玩具圈。又小又輕的圈轉得快、掉得也快，需要又快又慌的胯部動作。成年人用成人尺寸的圈，往往會覺得好駕馭得多。","從大圈開始。立在地上時，圈的高度大約到你的腰和胸之間，轉動得足夠慢，讓你能感受到節奏。較重的圈也帶有更多動量。之後你可以換小圈來追求速度和離身技巧。","脈衝，而不是畫圈。最常見的錯誤是想用胯部畫大圓。腰部呼啦圈通常是一個小的前後搖擺，或左右搖擺，與圈的節奏同步。一隻腳稍微向前會有幫助。圈碰到你的前面和後面；當它轉過來時，你輕輕推一下。","數拍子。一個放鬆的節奏，一拍一圈，讓你的身體有節奏可以安定下來。App 從慢速腰部呼啦圈開始，然後讓你逐步加速。如果圈往下沉，給你的脈衝加一點速度，而不是做更大的動作。","做好幾節課都在不停掉圈的心理準備，然後突然就不掉了。呼啦圈是那種會突然開竅的技能。一旦開竅，整個在身和離身的 flow 世界都在等著你，而且很多甚至不需要用到腰。"]},"unlocking-is-not-a-race":{"title":"解鎖不是一場競賽","summary":"獎勵樹會在你掌握基礎後開放更難的招式；重點在於基礎本身。","body":["SynthFlow 的獎勵就是招式。掌握了 cascade，reverse cascade 就會開放；掌握了 front spin，figure-8 就會出現。看著獎勵樹亮起來很有滿足感，我們也是特意這樣設計的。但任何解鎖系統都有一個陷阱，值得點明。","這個陷阱就是把掌握當成一個打勾的任務。你可以在狀態好的一天技術上記錄某個招式的乾淨完成次數，解鎖下一個，然後帶著一個只在一切順利時才管用的基礎繼續前進。然後更難的招式會顯得不可能，因為它們預設基礎在出問題時也能撐住。","在 flow 中，掌握意味著這個招式能在干擾下存活：一點疲勞、不同的節奏、有人從旁邊走過。這就是為什麼掌握要求跨多次練習的乾淨完成，而不只是一次。也是為什麼我們建議定期回到已掌握的招式。Cascade 不是一個你通關的關卡；它是整棵雜耍樹所站立的地面。","鎖定的招式也有頁面。你可以閱讀它們，在 3D 中觀看它們，看看它們需要什麼。向前看是很有動力的。沒有基礎就提前練，大多隻會讓人沮喪。","所以享受解鎖吧，但用你最老的招式有多輕鬆來衡量自己。當 cascade 變得無聊時，你就準備好學 Mills Mess 了。當 Mills Mess 變得無聊時，獎勵樹還有更多可以給你。"]},"practice-in-ten-minutes":{"title":"十分鐘的真實練習","summary":"熱身、一個重點招式、一個連線、一小段節奏爬升和放鬆：每天十分鐘。","body":["人們不練習最常見的理由是時間。事實是，flow 技能對短而頻繁的練習反應極好。以下是我們自己使用的十分鐘結構。","第一到第二分鐘：熱身。手腕繞環、手臂繞環、肩部滾動，如果你轉呼啦圈就做幾個胯部繞環。數著拍子，用放鬆的節奏，讓你的時機感隨著關節一起醒來。","第三到第五分鐘：你的重點招式。一個你正在練的招式，用你能幹淨完成的節奏。做幾個短的、數拍子的步驟，而不是一個長的，中間加一次呼吸。","第六到第七分鐘：一個連線。把重點招式和一個它能流入或流出的招式配對。Cascade 接 reverse cascade。Front spin 接 figure-8。腰部接胸部。連線是讓練習感覺像 flow 而不是訓練的原因。","第八到第九分鐘：一小段節奏爬升。兩到三個臺階，每個加幾 BPM，在動作變形前停下。在一個乾淨的臺階上結束。","第十分鐘：放鬆。一個緩慢、輕鬆的動作或短暫休息。記錄你的努力。完成。","每天十分鐘，一週就是一個多小時的專注練習，以協調性最喜歡的方式分散開來。當你告訴練習嚮導你時間不夠時，它會構建這種大小的課程，內建的短套路也遵循同樣的結構。"]},"antispin-broke-my-brain":{"title":"Antispin 讓我腦子炸了（炸了一週）","summary":"讓 staff 逆著手部的圓圈轉動感覺不可能，直到數拍給每片花瓣一個節拍。","body":["Antispin 是 staff spinning 開始感覺像幾何作業的地方。你的手朝一個方向畫圓，而 staff 朝另一個方向轉動，兩端描出一朵花。我第一次嘗試時，做出來的東西更像一朵蔫了的蒲公英。","有幫助的是讓這個形狀可以數拍。四瓣 antispin 有四個瞬間，其中一端直直地指向圓圈外。我給每一個一個節拍：上、側、下、側。然後我把音樂放慢到遠低於我正常 spinning 的節奏，只是瞄準節拍上的位置。","3D 檢視器裡的 ghost，會顯示 staff 在下一拍應該在哪裡，那周是我最好的朋友。trail 也是，它畫出我的花，讓我能看到花瓣什麼時候不均勻。通常底部的花瓣會被壓扁，因為我在圓圈底部趕了。","大約一週後，有些東西轉變了。我不再把手的動作和 staff 當成兩件事，而是開始把花感受為一個形狀。節奏自己就回來了。","如果 antispin 正在炸你的腦子，它本來就該這樣。給每片花瓣一個節拍，放慢音樂，讓你的身體自己解決。當它成功時，是 flow 中最好的感覺之一。"]},"siteswaps-for-the-maths-shy":{"title":"給怕數學的人的 siteswap","summary":"你不需要喜歡數學才能用 siteswap；你只需要知道數字越大，拋得越高。","body":["Siteswap 記法有嚇跑人的名聲。雜耍者會興高采烈地說“試試 531”，好像這就解釋了一切。它確實能解釋，但只有在你知道了幾個要點之後，而那些要點比看起來簡單。","以下幾乎就是你需要的一切。每個數字是一次拋接。數字越大，拋得越高。奇數會交叉到另一隻手；偶數會回到同一隻手。3 是普通的 cascade 拋接。1 是一次快速的橫向傳遞。2 通常只是拿著球。","這已經足夠讀懂 441：兩次較高的拋接留在自己這一側，然後一次橫向傳遞。你現在不用再讀一個字就能試了。拋、拋、傳，跟著節拍。","如果你還想要一塊拼圖：把數字相加，再除以數字的個數，就得到球的數量。4 + 4 + 1 = 9，除以 3 是 3 個球。如果答案不是整數，這個模式就無法雜耍。這就是著名的平均值定理的全部內容。","在 SynthFlow 中，每個雜耍招式都有一個 siteswap，3D 引擎直接根據它生成動畫。這意味著人物總是按照數字描述的高度、在準確的節拍上拋接。慢慢觀看一個 siteswap 的動畫，是我們所知道讓數字變得最容易理解的最快方法。不需要數學學位。"]},"music-that-fights-you":{"title":"當音樂和你作對時","summary":"一首與數拍相沖的曲目會讓每個招式都更難；測量過的節奏和生成的節拍可以解決這個問題。","body":["你大概感受過：一首你喜歡的歌，一個你熟悉的招式，但不知怎麼一切都不對。你趕拍、你掉、你怪自己。通常問題不在你，而在於這首歌的節奏和這個招式不匹配。","每個 flow 動作都有舒適的節奏範圍。低於它，旋轉道具會停滯；高於它，拋接會變得低而慌亂。128 BPM 的曲目配上喜歡 90 的呼啦圈動作，會讓你在音樂和呼啦圈之間做選擇。好訊息是半拍和雙拍能幫忙：128 可以承載 64 的動作，每兩拍一個迴圈。","漂移是更微妙的問題。如果音樂說 120，但計數說 116，兩者會在一分鐘內逐漸錯開，你的身體無法同時跟上兩者。這就是為什麼 SynthFlow 為內建曲目使用測量過的速度，以任何精確速度生成打擊樂，並用點選測試檢查你裝置上的曲目。","當曲目和你較勁時，不要硬碰硬。切換到該步驟的生成節拍，或讓構建器推薦合適範圍內的曲目。把你喜歡的歌留到自由練習，那裡不需要對齊。","音樂應該感覺像夥伴。如果感覺像對手，換音樂，而不是換你的動作。"]},"learning-alongside-my-kid":{"title":"和孩子一起學雜耍","summary":"兩個初學者，一袋球，一條規則：我們為掉落歡呼，和接住一樣大聲。","body":["我女兒想學雜耍，我意識到自己也不會。所以我們一起學，晚飯後十分鐘，每人三個豆袋，一條規則：我們為掉落歡呼，和接住一樣大聲。","這條規則聽起來很傻。結果它成了最重要的部分。孩子和大人一樣，在覺得犯錯很丟臉時會緊張。緊張會讓拋接更糟。為每次掉落歡呼，讓地板也成了遊戲的一部分，讓我們倆都保持放鬆。","我們從一顆球開始，跟著節拍在兩手之間拋，高度到眼睛。大約三次練習裡它都太簡單了，然後突然變得重要，因為兩球交換只有在那些單拋穩定時才成立。她比我先學會交換，還得意得讓人受不了。","有計數的音樂幫我們一起練習。同樣的速度，同樣的強拍，兩個人同時拋。當我們中有人丟了節奏，另一個繼續，掉的人會在下一個“一”回來。","四周後，我們都有了一個搖搖晃晃的 cascade。更重要的是，我們有了一個都期待的習慣。如果你有個想學東西的孩子，就和他們一起學。一起當初學者被低估了。"]},"why-your-throws-drift-forward":{"title":"為什麼你的拋接會向前偏移","summary":"如果你每次做完cascade都離起點三步遠，說明你的拋接在朝遠離你的方向傾斜。下面是讓它們回到原位的方法。","body":["每個雜耍者都熟悉這種走位。你在房間中央開始cascade，結束時鼻子已經貼到牆上，一步一步追著套路跑。感覺像是球在拽著你走。其實不是。是你在把球往前拋，每次偏幾釐米，然後走上去接。","原因幾乎總是手肘。當你緊張時，前臂會向前傾，手在身體稍前方釋放球。每次拋接都落得遠一點，於是下一次接也在更遠處，下一次拋又從更遠處開始。很快就累積起來了。","我首先教的是收肘。讓手肘貼近肋骨，前臂大致水平，把球筆直向上拋過眼睛，而不是拋到身前。第一天會覺得憋屈。然後就覺得穩了。","第二個方法是找面牆。面朝牆站，大約一前臂的距離，然後開始雜耍。如果拋接偏移，牆會立刻大聲告訴你。十分鐘的靠牆練習，比我說什麼都更快地讓身體記住豎直套路的感覺。","SynthFlow的攝像頭模式也會監測偏移。它會追蹤你的軀幹在攝像頭裡一步之內變大了多少，這意味著你在朝它走，然後用簡短提示提醒你。3D教練還能在乾淨拋接旁邊顯示前拋的殘影，讓你看到差別，而不只是聽到。","偏移不是性格缺陷。它是緊張的習慣，而習慣會隨著重複改變。收好手肘，向上拋而不是向外拋，讓牆幫你保持誠實。"]},"practising-to-a-click":{"title":"跟著節拍器練習","summary":"節拍器聽起來像是世界上最無聊的東西。結果它卻是讓我的flow感覺像跳舞的東西。","body":["我抗拒節拍器好多年。音樂對我來說就是flow arts的意義，而節拍器感覺像作業。後來一個打鼓的朋友看我雜耍，善意地說，我每次興奮就加速，每次害怕就減速。她說得對，而我完全沒意識到。","於是我試了一週只跟著節拍器練習。第一個發現是，穩定的脈衝比聽起來難。我的單手雙球套路想往前衝。我的staff figure-8在弱側想拖拍。節拍器不在乎我的感受；它只是保持時間。","第二個發現是，節拍器讓音樂變得更容易。一週後，當我重新放真實曲目時，我能感覺到節拍在聲音裡的位置。我不再和節奏鬆散的歌曲較勁，而是開始選擇要鎖定groove的哪個部分。","SynthFlow生成的打擊樂是節拍器更友好的版本。你可以選擇音色組，從純click到手鼓，它能以任何速度播放，所以一個套路可以正好活在你 hold 得住的速度上。它也能作為引導，在音樂曲目下輕聲執行。我每次練習的前幾分鐘仍然會單獨用它。","如果你想試試，選一個套路和一個感覺稍微太慢的速度。大聲數四小節，然後停止數數，只是聽。當套路和click感覺像同一個聲音時，加四BPM。這就是全部方法。"]},"staff-in-a-small-apartment":{"title":"小公寓裡的staff","summary":"一根1.4米的staff和2.4米的天花板可以共存。你只需要選好你的平面。","body":["我的公寓天花板低，有一個我很喜歡的燈具，樓下鄰居上夜班。這些對staff spinning都不理想。我在公園練了一年，才發現我的大部分訓練其實可以在室內進行。","訣竅是平面。Wheel-plane spins，也就是身體旁邊那些大旋轉，需要staff在頭頂上方有完整高度。身體前方的wall-plane work需要寬度，但高度要求較低。Floor-plane spins，比如helicopter，需要頭頂上方有空間，但小腿周圍不需要。每個房間支援不同的動作。","在客廳裡，我可以做isolations、front spins和手臂放低的慢速figure-8。在走廊裡我什麼都做不了，所以走廊用來做手腕熱身。臥室天花板最高，所以wheel-plane work在那裡進行，慢慢地做，燈具拆下來收進抽屜。","短staff也有幫助。一根比我的表演staff短一掌的練習staff，把很多差點撞到變成了輕鬆透過。時機會有一些變化，所以我每週會在戶外檢查一次全長staff。","為了鄰居：練習墊和軟頭staff。掉在瑜伽墊上是沉悶的砰聲，而不是啪的一聲。我也把室內練習限制在十分鐘的計數套路內，這樣噪音短，練習也專注。","SynthFlow讓你把家裡做不了的動作標記為不喜歡，這樣生成器就會把它們排除在室內套路之外。小空間不會阻止進步。它們只是讓你非常擅長isolations。"]},"hooping-after-40":{"title":"40歲之後玩hoop","summary":"我43歲第一次拿起hoop。我的背、膝蓋和自尊都有意見。下面這些方法有效。","body":["我在一個節慶後一時興起買了第一個成人hoop，確信自己會很糟。我確實很糟。但一個月內，我也能整首歌時間在腰上轉hoop，六個月內能做簡單的離身動作。年齡沒有阻止我。它只是改變了我需要怎麼練。","最大的教訓是好好熱身。髖部繞環、軀幹扭轉和輕柔的膝蓋彈動只要三分鐘，卻能讓當次練習的第一個hoop感覺順滑而不是嘎吱作響。SynthFlow把熱身放在每個套路的開頭是有原因的，而我在一個僵硬的早晨之後就再也不跳過了。","第二個教訓是hoop尺寸。更大、稍重的hoop轉得更慢，給你更多時間，也對下背要求更少。我開始用的hoop立在地上時到腰和胸之間，現在我仍然用它做長時間練習。","第三：脈衝，不要畫圈。初學者常把髖部畫圈擺動，這會讓脊柱扭轉超過必要。前後脈衝，或者如果hoop對你來說朝那個方向轉就左右脈衝，能用更少壓力讓hoop保持在上。如果你看髖部而不是hoop，3D教練會清楚展示這一點。","最後，短而頻繁勝過長而偶爾。每週四次十分鐘對我來說比周日一小時更有用。我的身體在兩次之間恢復，動作也記住了。","如果你超過40歲並且好奇，就開始吧。Hoop不知道你多大。"]},"fire-and-the-beginner":{"title":"火與初學者","summary":"火舞是flow arts最顯眼的部分，也是初學者問得最多的部分。誠實的答案是：還不行，而且不要獨自練。","body":["每週都有人問我們SynthFlow什麼時候教火。這個問題很合理。火很美，很多spinner都是在夜裡看到fire circle後進入這個圈子的。但我們永遠不會指導任何人點燃道具，這篇文章解釋為什麼。","火增加了與技巧無關的危險：燃料處理、衣物、風、觀眾、燒傷和滅火。這些要在現場向有經驗的人學習，有受過訓練的安全員在場，並準備好合適裝置。App無法檢查你的燃料桶、你的棉質衣物或你的安全毛巾。","App能做的是幫助你在接近火之前建立火所需要的技能。這意味著你能用練習道具穩定地、以穩定速度、不掉落地完成整首歌的動作。如果一個套路在家裡用練習道具還會讓你意外，那它還沒準備好上fire。","火圈社群有個有用的測試：你能在半閉眼、黑暗中、有人跟你說話時完成這套動作嗎？火又亮又熱又吵，會佔據你的注意力。你的身體必須能在無人監督下知道動作。","LED道具是很好的中間步驟。它們給你夜晚的視覺效果、光軌和觀眾反應，卻沒有風險。SynthFlow的LED風格包會展示你的套路點亮後的樣子，這也是發現平面不整齊的好方法。","當你準備好時，找一個當地的火舞聚會，自我介紹，並請求先學習安全知識。在那之前，用練習道具旋轉。火一直在那裡等你。"]},"four-balls-taught-me-patience":{"title":"四個球教會了我耐心","summary":"從三個球過渡到四個球花的時間比最初學三個球還長，而且它改變了我對練習的看法。","body":["三個球花了我五週。四個球花了五個月。沒人警告過我這一點，所以我來警告你：四個球不是三個球加一個。它是一個完全不同的模式，你的身體必須從頭學起。","在四球噴泉中，每隻手獨立拋接兩個球，球從不交叉。雙手通常交替，但彼此之間完全沒有交換。我之前學到的關於從另一隻手接球的一切突然變得毫無用處。","所以我回到單手練習。右手兩個球，先練柱式，再練圓圈，直到我能不加思考地拋五十次。然後左手，花了三倍的時間。然後雙手一起，先同步，再交替。SynthFlow 的節奏階梯在這裡幫了大忙：每週我從噴泉節奏範圍的最低端開始，只有在一次乾淨的完成後才往上走。","耐心的教訓來自平臺期。有些周沒有任何進步。我還是記錄了掉落和乾淨完成次數，圖表顯示即使感覺沒有進步時也有緩慢的進展。資料讓無聊的幾周變得可以忍受。","另一個教訓是關於休息。四個球讓我的前臂疲勞的方式是三個球從未有過的。當我每天練習時，我變得更差。當我隔天練習時，我變得更好。握力肌肉和其他肌肉一樣需要恢復。","如果你卡在三個和四個之間，把問題拆開，相信緩慢的幾周，給你的前臂放一天假。它終會到來。"]},"the-escalator-and-hand-traffic":{"title":"電梯式和手部交通的藝術","summary":"呼啦圈的手部動作看起來像魔法，直到你發現它們只是兩隻手之間仔細的交通管理。","body":["我第一次看到電梯式時，呼啦圈似乎沿著轉圈者的手臂向上爬，然後又飄下來，無休無止，沒有明顯的抓握。我以為這需要多年的練習。實際上大約三週就夠了，一旦我明白它只是一種交接的模式。","幾乎每一個離體呼啦圈動作都關乎哪隻手握住呼啦圈、何時鬆手、另一隻手在哪裡接住。如果雙手之間的時機模糊，呼啦圈就會晃出它的平面，動作就會散架。如果時機乾淨，呼啦圈看起來就像自己在移動。","所以我開始給交接命名。在 SynthFlow 的數拍中，我大聲說出左右手而不是數字：右、左、右、左，每一拍一個。跟著音樂說出來迫使我注意到左手何時提前抓了。提前抓幾乎是每一次晃動的根源。","第二個關鍵是讓呼啦圈保持在它的平面內。抓握時扭轉的手會傾斜呼啦圈，而傾斜的呼啦圈半秒後就是掉落的呼啦圈。平面疊加在這裡很有幫助，在鏡子前用慢速節奏練習也很有用。","一旦電梯式變得可靠，其他手部動作就來得更快了。Isolation、傳遞和套索都使用同樣的理念：清晰的交接、平坦的平面、穩定的時機。魔法只是交通管理。"]},"behind-the-back-without-fear":{"title":"無所畏懼的背後傳遞","summary":"棍的背後傳遞是大多數旋轉者停滯的地方。問題通常不是技術，而是想看的衝動。","body":["有好幾個月，我的背後傳遞只是一個帶著希望扭轉的前面傳遞。我會開始動作，當棍離開視線時驚慌，然後把它帶回身前。棍實際上從未到過我背後。我的大腦不讓它去。","突破來自於接受我看不到這個動作。你無法觀看背後傳遞。你必須從鬆手的那隻手感受棍在哪裡，並信任等待的那隻手。","我用慢動作訓練那種感覺。完全不旋轉，我在背後傳遞棍，手到手，眼睛向前看。然後先加一個慢的半轉。然後在動作節奏範圍的最低端，數著拍子。每一步都感覺傻。每一步都有效。","3D 教練出乎意料地有用，因為我可以旋轉視角從後面觀看動作。看到雙手在哪裡相遇，以及棍在繞行時如何保持在牆面平面內，給了我的身體一張從正面無法獲得的地圖。","第二個恐懼是打到自己。一根軟頭練習棍和一塊大而空曠的空間解決了這個問題。一旦我知道犯錯只會帶來輕輕一碰而不是淤青，我就不再畏縮了，而畏縮一直是導致失誤的原因。","如果背後傳遞仍然讓你害怕，把它放慢，去掉旋轉，保持眼睛向前看。你的手知道的比你想象的多。"]},"why-reverse-feels-wrong":{"title":"為什麼反向 cascade 感覺不對","summary":"反向 cascade 使用與 cascade 相同的手、相同的球和相同的節奏。那為什麼感覺像從頭開始？","body":["當我學反向 cascade 時，我以為一個下午就夠了。同樣的三個球、同樣的交替雙手、同樣的節奏。結果花了三週，我搞不懂為什麼。","答案是方向。在正常的 cascade 中，每個球從模式的內部丟擲，在外側接住。在反向 cascade 中，球從外側丟擲，越過 incoming 球的頂部，在內側接住。你的手在製造同樣的節奏，但完全不同的形狀。","新的形狀打破了你的時機。在 cascade 中，你在 incoming 球開始下落時丟擲。在反向中，你需要稍微早一點丟擲，讓你的球越過另一個球的頂部。在舊的時刻丟擲，球就會相撞。","我先用兩個球解決。兩個球，反方向，跟著節拍數數，直到感覺自動化。然後三個球用慢速節奏，大聲數拍。SynthFlow 的幽靈疊加向我展示了一個典型錯誤——拋得太低擦到另一個球——我能看到我正是那樣做的。","一旦開竅，它解鎖了很多東西。混合 cascade 和反向是許多技巧的基礎，反向的形狀在 Mills Mess 中再次出現。三週做不好是值得的。"]},"making-a-prop-stand-still":{"title":"Isolation：讓道具靜止不動","summary":"Isolation 是一種道具似乎停在一個地方而你繞著它移動的動作。它是 flow arts 中最令人滿足的幻覺。","body":["我第一次成功做出棍的 isolation 時，朋友問棍是怎麼漂浮的。當然它不是漂浮的。我的手在畫一個仔細的圓圈，讓棍上的一個點固定在空氣中。但從外面看它像是不可能的，那種感覺就是我熱愛 isolation 的原因。","每個 isolation 的原理都一樣。在道具上選一個點，通常是中心或一端，讓那個點保持不動，同時道具的其餘部分旋轉。你的手必須以與道具想要移動的方向完全相反的方式移動。它是反直覺的，而且有點催眠。","最難的部分是你的身體也在移動。臀部偏移、肩膀轉動，每一個小動作都會在固定點上表現為晃動。我在鏡子前練習，用一塊膠帶標出固定點應該在的位置。如果道具的中心離開了膠帶，我就知道了。","呼啦圈的 isolation 遵循同樣的理念。在 SynthFlow 中，我開啟 3D 檢視器中的軌跡，觀察教練：在乾淨的 isolation 中，固定點周圍的軌跡保持很小。當我把節奏放慢並模仿時，我能感覺到我的手在每個圓圈的頂部漂移。","Isolation 還建立了幫助其他一切的控制力。一旦你能讓道具靜止，你就可以把它放在你選擇的任何位置。平面變得更平，過渡變得更乾淨，你的 flow 開始看起來是有意為之而不是靠運氣。","慢慢開始，標出固定點，像鷹一樣盯著它。然後展示給朋友，享受他們的表情。"]}}`),i={"zero-to-cascade":{name:`四周從零到 cascade`,description:`一顆球，然後兩顆，然後第三顆加入。每天短時間練習就夠了：完成每週的 routine 來掌握它的動作，並解鎖下一週。`,weeks:[{label:`第 1 周 · 一顆球`},{label:`第 2 周 · 兩顆球`},{label:`第 3 周 · 第三顆球`},{label:`第 4 周 · Cascade`}]},"beyond-the-cascade":{name:`超越瀑布式`,description:`四周的三球花樣：先網球與爪接，再繞身拋接，最後是每次拋兩球的同步模式。`,weeks:[{label:`第 1 周 · 網球與爪接`},{label:`第 2 周 · 半淋浴`},{label:`第3周 · 身體拋接`},{label:`第4周 · 豎列拋接`}]},"first-clubs":{name:`初試雜耍棒`,description:`從讓一根雜耍棒轉起來,到穩定的三棒瀑布式拋接,再用雙旋練高度和轉速的控制。`,weeks:[{label:`第1周 · 單棒`},{label:`第2周 · 交換拋`},{label:`第3周 · 瀑布式拋接`},{label:`第4周 · 雙旋`}]},"passing-with-a-partner":{name:`與搭檔傳接`,description:`兩名雜耍者面對面。先傳一個球，再各持兩球同拍對傳，然後各持三球練六拍、四拍和兩拍。`,weeks:[{label:`第1周 · 單球對傳`},{label:`第2周 · 各持兩球`},{label:`第3周 · 六拍與四拍`},{label:`第4周 · 兩拍`}]},"staff-foundations":{name:`Staff 基礎`,description:`輪轉和正面旋轉、figure 8 和 pass-through：幾乎所有 staff flow 都建立在這四個動作上。`,weeks:[{label:`第 1 周 · 輪轉`},{label:`第 2 周 · 正面旋轉`},{label:`第 3 周 · Figure 8`},{label:`第 4 周 · Pass-through`}]},"staff-contact":{name:`接觸長棍`,description:`一週周放鬆握持:先練方向盤和魚尾,再練手上滾轉,最後讓長棍在前臂上轉起來。`,weeks:[{label:`第1周 · 方向盤`},{label:`第2周 · 魚尾`},{label:`第3周 · 手上滾轉`},{label:`第4周 · 前臂滾轉`}]},"double-staff-start":{name:`雙棍入門`,description:`從兩棍同步起步,練到分拍,再練兩側的車輪。`,weeks:[{label:`第1周 · 同步`},{label:`第2周 · 分拍`},{label:`第3周 · 車輪`},{label:`第4周 · 分拍車輪`}]},"hoop-body-ladder":{name:`呼啦圈身體階梯`,description:`先把腰上轉圈練到兩個方向都穩,再往下到胯部和大腿,最後上提到胸口。`,weeks:[{label:`第1周 · 雙向`},{label:`第2周 · 胯部`},{label:`第3周 · 大腿`},{label:`第4周 · 提到胸口`}]},"hoop-doubles-start":{name:`雙圈入門`,description:`一手一個圈:先練映象旋轉、錯位旋轉、側向旋轉,最後練一個在腰上、一個在手上。`,weeks:[{label:`第1周 · 映象旋轉`},{label:`第2周 · 錯位旋轉`},{label:`第3周 · 側向旋轉`},{label:`第4周 · 一腰一手`}]},"off-body-hoop":{name:`離體呼啦圈`,description:`從單手轉呼啦圈到 lasso、pass、wedgie，以及讓呼啦圈看起來漂浮的 isolation。`,weeks:[{label:`第 1 周 · 手轉`},{label:`第 2 周 · Lasso 和 pass`},{label:`第 3 周 · Wedgie`},{label:`第 4 周 · Isolation`}]},"first-poi":{name:`初識 Poi`,description:`先練單隻 poi，再加一對：雙向牆面旋轉、身側車輪旋轉，然後是分時。`,weeks:[{label:`第 1 周 · 單 poi`},{label:`第 2 周 · 牆面旋轉`},{label:`第 3 周 · 車輪旋轉`},{label:`第 4 周 · 分時`}]},"poi-weave-ladder":{name:`Poi 編織階梯`,description:`從追日到雙向三拍編織，再到更快的兩拍編織。`,weeks:[{label:`第 1 周 · 追日`},{label:`第 2 周 · 三拍編織`},{label:`第 3 周 · 反向編織`},{label:`第 4 周 · 兩拍編織`}]},"poi-antispin-start":{name:`反旋入門`,description:`先練延展和隔離，然後是單 poi 反旋，最後用雙 poi 練四瓣花。`,weeks:[{label:`第 1 周 · 延展`},{label:`第 2 周 · 隔離`},{label:`第 3 周 · 單 poi 反旋`},{label:`第 4 周 · 反旋花式`}]}},a={"sf-ambient-70":{name:`慢速環繞`},"sf-world-75":{name:`市集步`},"sf-ambient-80":{name:`燈籠漂移`},"sf-world-85":{name:`沙漠之輪`},"sf-handdrum-90":{name:`圓鼓`},"sf-funk-95":{name:`松腕`},"sf-handdrum-100":{name:`火光之手`},"sf-world-105":{name:`河鈴`},"sf-funk-110":{name:`口袋瀑布`},"sf-handdrum-115":{name:`庭院律動`},"sf-electronic-120":{name:`霓虹棍`},"sf-funk-125":{name:`彈跳模式`},"sf-electronic-130":{name:`畫素呼啦圈`},"sf-handdrum-135":{name:`日落金貝鼓`},"sf-electronic-140":{name:`LED 拖尾`},"sf-funk-145":{name:`旋轉迴圈`},"sf-electronic-150":{name:`頻閃流`},"sf-handdrum-155":{name:`快速掌轉`},"sf-electronic-160":{name:`夜間旋轉者`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};